function heartbeatOn(){const h=state.system?.heartbeat;return typeof h==='boolean'?h:h&&typeof h==='object'?!!h.enabled:!!(state.system?.heartbeatEnabled ?? state.settings?.heartbeatEnabled ?? state.settings?.heartbeat);}
function isDemo(){return state.settings?.mode!=='api';}

async function api(path, options={}){
 const controller=new AbortController();const {timeoutMs=20000,...fetchOptions}=options;const timeout=setTimeout(()=>controller.abort(),timeoutMs);
 try{const res=await fetch(path,{...fetchOptions,headers:{'Content-Type':'application/json',...(options.headers||{})},signal:controller.signal});let body={};try{body=await res.json();}catch{if(!res.ok)throw new Error(`服务返回 ${res.status}`);}if(!res.ok){const failure=new Error(body.error||`请求失败（${res.status}）`);if(typeof body.code==='string'&&/^[A-Z_0-9]{1,80}$/.test(body.code))failure.code=body.code;throw failure;}return body;}catch(err){if(err.name==='AbortError')throw new Error('请求等待超时；操作可能仍在进行，请查看最新状态，勿重复提交');throw err;}finally{clearTimeout(timeout);}
}
function post(path,body={},options={}){return api(path,{...options,method:'POST',body:JSON.stringify(body)});}
function toast(message,error=false){clearTimeout(toast.timer);$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}">${icon(error?'alert':'check')}<span>${esc(message)}</span></div>`;toast.timer=setTimeout(()=>{$('#toast-root').innerHTML='';},5000);}
function readActiveChat(){try{const value=sessionStorage.getItem('luheng-active-chat');return value&&/^[a-zA-Z0-9_-]{1,160}$/.test(value)?value:null;}catch{return null;}}
function selectActiveChat(id){chatTaskId=id;try{if(id)sessionStorage.setItem('luheng-active-chat',id);else sessionStorage.removeItem('luheng-active-chat');}catch{}}
function navigate(next){if(!views[next])return;view=next;search='';navigationVersion++;location.hash=next;document.body.classList.remove('nav-open');render(true);window.scrollTo({top:0,behavior:'instant'});}
function formatOutput(value){let text=esc(str(value));return text.replace(/^###? (.+)$/gm,'<h3>$1</h3>').replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>');}
function artifactInfo(artifact){if(!artifact)return null;const filename=typeof artifact==='string'?artifact:artifact.filename||artifact.name||artifact.path?.split('/').pop();if(!filename)return null;let url=typeof artifact==='object'?artifact.url:null;if(!url||!url.startsWith('/api/artifacts/'))url='/api/artifacts/'+encodeURIComponent(filename.split('/').pop());return {filename,url,name:typeof artifact==='object'?artifact.name||filename:filename};}
function renderChrome(){
 const navButton=(key,label)=>`<button class="nav-item ${view===key?'active':''}" data-nav="${key}" ${view===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span>${key==='tasks'&&state.tasks.length?`<span class="nav-count">${state.tasks.length}</span>`:''}</button>`;
 const navMarkup=navButton('chat','智能对话')+navButton('tasks','任务记录')+`<button class="nav-item nav-disclosure ${toolsOpen?'expanded':''}" data-action="toggle-tools" aria-expanded="${toolsOpen}" aria-controls="nav-tools">${icon('panel')}<span>更多工具</span>${icon('chevron','nav-chevron')}</button><div id="nav-tools" ${toolsOpen?'':'hidden'}>${Object.entries(views).filter(([key])=>!['chat','tasks','settings'].includes(key)).map(([key,label])=>navButton(key,label)).join('')}</div>`+navButton('settings','设置');
 if($('#nav').innerHTML!==navMarkup)$('#nav').innerHTML=navMarkup;
 $('#page-label').textContent=views[view];$('#connection').className='connection'+(online?'':' offline');$('#connection').innerHTML=`<i></i>${online?'本地服务已连接':'本地服务未连接'}`;
 $('#mode-chip').className='mode-chip'+(isDemo()?'':' live');$('#mode-chip').textContent=isDemo()?'任务演示模式':'任务 API 模式';
 $('.new-task-button kbd').textContent=/Mac/i.test(navigator.platform)?'⌘ K':'Ctrl K';$('.mobile-menu').innerHTML=icon('menu');$('#notification-button').innerHTML=icon('bell')+(state.reminders.some(r=>['fired','sent','due'].includes(r.status))||pendingApprovals().length||pendingMailApprovals().length?'<i class="notification-dot"></i>':'');
 $('#heartbeat-card').hidden=!toolsOpen;
 $('#heartbeat-card').innerHTML=`<div class="heartbeat-card"><div class="heartbeat-card-top">${icon('heart')}<span>主动检查</span><button class="toggle ${heartbeatOn()?'on':''}" data-action="heartbeat" role="switch" aria-checked="${heartbeatOn()}" aria-label="${heartbeatOn()?'关闭':'开启'}主动检查"></button></div><p>${heartbeatOn()?'按本地周期检查任务与提醒':'开启后检查提醒与周期任务'}<br>周期任务沿用模式与权限；API 调用可能计费</p></div>`;
}
function render(force=false){
 renderChrome();
 main.dataset.view=view;
 if(!loaded){if(!online)main.innerHTML=`<div class="error-page">${icon('link')}<h2>工作空间暂未连接</h2><p>请确认本地服务已启动。连接恢复后，任务与设置会自动重新加载。</p><button class="secondary-button" data-action="refresh">${icon('refresh')}重新连接</button></div>`;return;}
 if(!force&&view==='settings'&&$('#settings-form'))return;
 if(!force&&document.activeElement&&main.contains(document.activeElement)&&['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){pendingRender=true;return;}
 pendingRender=false;
 const html=({chat:renderHome,tasks:renderTasks,schedules:renderSchedules,agents:renderAgents,knowledge:renderKnowledge,mail:renderMail,browser:renderControlled,audit:renderAudit,settings:renderSettings}[view])();
 const threadScroll=$('.chat-thread')?.scrollTop||0;
 main.innerHTML=(!online?'<div class="connection-banner">连接已中断，当前显示最近一次读取的数据。服务恢复后将自动同步。</div>':'')+html;
 if($('.chat-thread'))$('.chat-thread').scrollTop=threadScroll;
 applyBusyButtons();
}
function roadArt(){return `<div class="welcome-background" aria-hidden="true"><svg viewBox="0 0 520 210" fill="none"><defs><linearGradient id="sea-a" x1="70" y1="0" x2="450" y2="210"><stop stop-color="#d8ecff" stop-opacity=".2"/><stop offset="1" stop-color="#b1d6f8" stop-opacity=".55"/></linearGradient></defs><ellipse cx="260" cy="114" rx="213" ry="66" fill="url(#sea-a)"/><path d="M23 137c88-26 123-20 196 6 83 31 155 26 278-15M59 159c117-35 199 34 358 1" stroke="#a3cbed" stroke-opacity=".4"/><path d="M75 116h370M90 111c82-7 140-11 209-5 72 6 112 2 147-4M147 110V62m-4 48V62m201 43V45m-5 60V45" stroke="#8ebce5" stroke-width="1.5"/><path d="m89 111 57-46 56 42m-91 4 35-46 35 44m54-3L342 49l102 53m-68 2-34-55-39 56m-31 1 70-57 69 54" stroke="#aecfec"/><path d="m162 128 13-7 12 6 16 7h-55l14-6Zm191 19 15-9 12 5 15-12 20 9 12 9h-79l5-2Z" fill="#c9e0f5"/><circle cx="118" cy="45" r="3" fill="#7fb9ed"/><circle cx="393" cy="69" r="3" fill="#7fb9ed"/><path d="m99 65 21-18 45 7m230 17 32 17" stroke="#a6caed" stroke-dasharray="3 6"/><circle cx="166" cy="55" r="2" fill="#a0c8ec"/></svg></div>`;}
function renderComposer(hasTask=false){return `<form class="composer" id="task-form"><div class="composer-topline">${icon('spark')}<span>${hasTask?'下一件事，也可以交给路衡':'说说你想完成的工作'}</span></div><textarea id="prompt-input" name="prompt" aria-label="任务描述" placeholder="${hasTask?'描述下一项任务，将作为新任务独立执行…':'帮我整理资料、写一份周报，或推进一项工作…'}" required maxlength="12000">${esc(draft)}</textarea><div class="composer-tools"><div class="composer-meta"><button type="button" class="composer-options-toggle" data-action="toggle-options" aria-expanded="${optionsOpen}" aria-controls="composer-options">${icon('agents')}<span>${esc(draftAgent?getAgent(draftAgent)?.name||'指定助手':'自动协作')}</span>${icon('chevron')}</button><div class="composer-options" id="composer-options" ${optionsOpen?'':'hidden'}><label class="agent-select">${icon('agents')}<select name="agentId" id="agent-select" aria-label="选择执行智能体">${agentOptions(draftAgent)}</select></label><span class="composer-budget">执行预算 ${esc(state.settings.budget||20)} 步</span><button type="button" class="text-link" data-nav="settings">模型与高级设置 ↗</button></div></div><div class="composer-send"><span class="send-shortcut">Ctrl / ⌘ ↵</span><button class="send-button ${submitting?'loading-button':''}" aria-label="开始执行任务" type="submit" ${submitting?'disabled':''}>${submitting?'<span class="spinner"></span><span>提交中</span>':'<span>发送</span>'+icon('send')}</button></div></div></form><p class="composer-note">${icon('shield')}<span>${isDemo()?'当前为本地体验模式，尚未连接真实大模型。':'任务资料将发送至已配置的模型服务，重要操作先确认。'} <button class="text-link" data-nav="settings">${isDemo()?'连接模型':'查看设置'}</button></span></p>`;}
function renderHome(){
 const running=state.tasks.filter(taskActive).length,completed=state.tasks.filter(taskDone).length;
 const current=state.tasks.find(t=>t.id===chatTaskId);
 const examples=[['file','整理养护周报','汇总待办与巡查记录，形成一份可下载的周报','汇总演示养护待办并生成周报'],['browser','办理 OA 事务','打开模拟 OA，审批后提交巡查安排','在模拟OA提交一条巡查安排'],['mail','起草协调邮件','整理工作背景，起草一封养护协调邮件','起草一封养护协调邮件'],['clock','设置工作提醒','把下一件重要的小事，交给路衡记住','请5分钟后提醒我检查台账']];
 return `<div class="home-toolbar"><span class="workspace-caption">LUHENG · INTELLIGENT WORKSPACE</span><button class="overview-toggle" data-action="toggle-overview" aria-expanded="${overviewOpen}" aria-controls="home-overview">${icon('panel')}${overviewOpen?'收起工作工具':'工作工具'}</button></div><div class="home-grid ${overviewOpen?'overview-open':''} ${current?'has-conversation':''}"><section class="home-main">${current?`<div class="chat-thread">${renderTaskDetail(current)}</div>`:`<div class="welcome">${roadArt()}<span class="welcome-logo"><img src="/agent-mark.svg" alt="路衡"></span><div class="page-kicker">山海之间 · 从容向前</div><h1>复杂的工作，<span>简单地交给我。</span></h1><p>你说目标，路衡来协作。</p></div>`}${renderComposer(!!current)}<details class="recent-section" ${recentOpen?'open':''}><summary class="recent-disclosure">${icon('chevron')}最近的任务<span class="recent-count">${state.tasks.length} 项记录</span></summary><div class="recent-content"><button class="text-link" data-nav="tasks">查看全部任务 ↗</button>${state.tasks.length?state.tasks.slice(0,3).map(t=>`<button class="compact-task" data-task="${esc(t.id)}"><span class="task-mini-icon">${icon(taskDone(t)?'check':taskActive(t)?'clock':'file')}</span><span><strong class="compact-task-title">${esc(t.title||t.prompt)}</strong><span class="compact-task-meta">${esc(getAgent(t.agentId)?.name||'办公助手')} · ${date(t.createdAt)}</span></span>${badge(t.status)}</button>`).join(''):`<div class="compact-empty">${icon('tasks')}<span>还没有任务。写下想完成的工作，就可以开始。</span></div>`}</div></details></section>
 <aside class="home-rail" id="home-overview" aria-label="工作工具与概览" ${overviewOpen?'':'hidden'}><div class="rail-heading">常用工作 <button class="icon-button" data-action="toggle-overview" aria-label="收起工作工具">${icon('close')}</button></div><div class="suggestions">${examples.map(([i,t,d,p],idx)=>`<button class="suggestion-card" title="${d}" data-action="${idx===3?'reminder':'sample'}" data-prompt="${esc(p)}"><span class="suggestion-icon">${icon(i)}</span><span><strong>${t}</strong><p>${d}</p></span></button>`).join('')}</div><div class="rail-heading rail-section-title">工作概览</div><div class="rail-panel"><div class="rail-panel-body"><div class="metric-row"><div class="metric"><b>${running}</b><span>正在推进</span></div><div class="metric"><b>${completed}</b><span>已完成任务</span></div></div></div></div><div class="rail-note"><strong>${icon('knowledge')}资料与知识</strong><p>补充工作资料，让路衡更懂你的业务。</p><button class="text-link" data-nav="knowledge">管理知识资料 ↗</button></div><div class="rail-note rail-reminder"><strong>${icon('clock')}工作提醒</strong><p>${state.reminders.filter(r=>!['fired','sent','cancelled','completed'].includes(r.status)).slice(0,1).map(r=>`${esc(r.title)}<br>${date(r.dueAt)}`).join('')||'暂无待提醒事项。'}</p><button class="text-link" data-action="reminder">添加提醒 ＋</button></div></aside></div><p class="privacy-footer">路衡 · 让协作更从容</p>`;
}
function agentOptions(selected){const agents=state.agents.filter(a=>a.enabled!==false);return `<option value="">自动选择助手</option>`+agents.map(a=>`<option value="${esc(a.id)}" ${String(a.id)===String(selected)?'selected':''}>${esc(a.name)}</option>`).join('');}
function pageHeading(kicker,title,description,action=''){return `<div class="page-heading"><div><div class="page-kicker">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function empty(iconName,title,description,action=''){return `<div class="empty-state">${icon(iconName)}<h3>${title}</h3><p>${description}</p>${action}</div>`;}
function renderTasks(){
 let tasks=state.tasks.filter(t=>taskFilter==='all'||taskFilter==='active'&&taskActive(t)||taskFilter==='done'&&taskDone(t)||taskFilter==='issues'&&['failed','cancelled','canceled','error','rejected','needs_attention'].includes(t.status));if(search)tasks=tasks.filter(t=>(t.title+' '+t.prompt).toLowerCase().includes(search.toLowerCase()));
 if(!selectedTaskId&&tasks.length)selectedTaskId=tasks[0].id;const selected=getTask();
 return pageHeading('TASK CENTER','每一件事，都有着落','从开始执行到最终交付，完整保留任务的来龙去脉。',`<button class="primary-button" data-action="new-task">${icon('plus')}新任务</button>`)+
 `<div class="view-toolbar"><div class="tabs">${[['all','全部任务'],['active','进行中'],['done','已完成'],['issues','未完成']].map(([key,label])=>`<button class="tab ${taskFilter===key?'active':''}" data-filter="${key}">${label}</button>`).join('')}</div><label class="search-field">${icon('search')}<input id="task-search" placeholder="搜索任务" aria-label="搜索任务" value="${esc(search)}"></label></div>`+
 (!state.tasks.length?empty('tasks','从一句话开始','描述想完成的工作，路衡会把它拆成可追踪的步骤。',`<button class="primary-button" data-action="new-task">${icon('plus')}发起第一个任务</button>`):`<div class="task-workspace"><div class="task-list">${tasks.length?tasks.map(t=>`<button class="task-card ${String(selectedTaskId)===String(t.id)?'selected':''}" data-task="${esc(t.id)}"><div class="task-card-top">${badge(t.status)}<time>${date(t.createdAt)}</time></div><h3>${esc(t.title||t.prompt)}</h3><span class="task-card-agent">${icon('agents')}${esc(getAgent(t.agentId)?.name||'办公助手')}</span></button>`).join(''):empty('search','没有匹配的任务','试试其他关键词，或切换任务分类。')}</div>${selected?renderTaskDetail(selected):empty('tasks','选择一个任务','点击左侧任务，查看执行步骤与结果。')}</div>`);
}
function renderTaskDetail(t){
 const approvals=pendingApprovals().filter(a=>String(a.taskId)===String(t.id));const artifact=artifactInfo(t.artifact);const budget=Math.max(1,Number(t.budget||state.settings.budget||20));const used=Number(t.budgetUsed||0);
 return `<article class="task-detail"><div class="detail-top"><div class="detail-topline">${badge(t.status)}<div class="button-row">${taskActive(t)?`<button class="secondary-button small-button" data-action="cancel-task" data-id="${esc(t.id)}">${icon('pause')}取消任务</button>`:''}${t.output?`<button class="icon-button" data-action="copy-output" data-id="${esc(t.id)}" aria-label="复制任务结果">${icon('copy')}</button>`:''}</div></div><h2>${esc(t.title||t.prompt)}</h2><div class="detail-meta"><span>${icon('agents')}${esc(getAgent(t.agentId)?.name||'办公助手')}</span><span>${icon('clock')}${date(t.createdAt)}</span><span>预算 ${used} / ${budget} 步</span></div><div class="budget-progress"><i style="width:${Math.min(100,used/budget*100)}%"></i></div></div><div class="detail-body"><h3 class="detail-label request-label">${icon('chat')} 你的需求</h3><div class="prompt-block">${esc(t.prompt)}</div>
 ${array(t.steps).length?`<details class="execution-disclosure" data-execution-task="${esc(t.id)}" ${(executionOpen.has(t.id)?executionOpen.get(t.id):view!=='chat'||taskActive(t))?'open':''}><summary class="detail-label">${icon('chevron')}执行过程 <span>${array(t.steps).length} 个步骤</span></summary><div class="steps">${t.steps.map((s,i)=>`<div class="step ${esc(s.status)}"><span class="step-icon">${['completed','succeeded','done','success'].includes(s.status)?'✓':['failed','error'].includes(s.status)?'!':s.status==='running'?'•':i+1}</span><h4>${esc(s.name||s.title||'执行步骤')}</h4>${s.detail?`<p>${esc(str(s.detail))}</p>`:''}</div>`).join('')}</div></details>`:taskActive(t)?'<div class="compact-empty"><span class="spinner"></span>任务已进入队列，等待开始执行。</div>':''}
 ${approvals.map(a=>a.type==='browser.actions'?`<div class="approval-box"><h3>${icon('browser')}网页输入等待完整审批</h3><p>${esc(a.summary)}<br>首次填写或点击前，请核对目标、控件和每个确切输入值。</p><button class="primary-button small-button" data-action="open-controlled-approval" data-id="${esc(a.controlledApprovalId)}">到浏览器工作台审核确切动作</button></div>`:a.type==='mail.send'?`<div class="approval-box"><h3>${icon('mail')}真实邮件等待完整审批</h3><p>${esc(str(a.summary))}<br>请到邮件工作台核对全部收件人、服务商、主题和正文后再批准。</p><button class="primary-button small-button" data-action="open-mail-approval" data-id="${esc(a.serviceApprovalId)}">到邮件工作台审核完整内容</button></div>`:`<div class="approval-box"><h3>${icon('shield')}需要你的确认</h3><p>${esc(str(a.summary||a.description||'即将执行需要审批的操作，请确认后继续。'))}</p><div class="button-row"><button class="primary-button small-button" data-action="approve" data-id="${esc(a.id)}" ${t.browserSession?.status==='manual'?'disabled title="请先归还浏览器控制权"':''}>${icon('check')}${t.browserSession?.status==='manual'?'请先归还控制权':'确认并继续'}</button><button class="secondary-button small-button" data-action="reject" data-id="${esc(a.id)}">拒绝本次操作</button></div></div>`).join('')}
 ${t.browserSessionId?renderBrowser(t):''}${t.controlledSessionId?`<div class="info-banner">${icon('browser')}此任务拥有一个隔离网页会话。<button class="text-link" data-action="open-controlled-session" data-id="${esc(t.controlledSessionId)}">查看受控浏览器 ↗</button></div>`:''}
 ${t.error?`<div class="approval-box" style="background:#fff5ef;border-color:#ead5c7"><h3>${icon('alert')}任务未完成</h3><p>${esc(str(t.error))}</p>${t.status==='needs_attention'?`<p>请先人工核实${t.controlledSessionId?'网页输入结果':'邮件状态'}；此任务不提供重试。</p>${t.controlledSessionId?`<button class="secondary-button small-button" data-action="open-controlled-session" data-id="${esc(t.controlledSessionId)}">查看网页会话</button>`:''}${t.mailDraftId?`<button class="secondary-button small-button" data-action="open-mail-draft" data-id="${esc(t.mailDraftId)}">查看邮件状态</button>`:''}`:`<button class="secondary-button small-button" data-action="retry-task" data-id="${esc(t.id)}">编辑后重新发起</button>`}</div>`:''}
 ${t.output?`<h3 class="detail-label response-label">${icon('spark')}路衡 · 任务结果</h3><div class="output-block task-result">${formatOutput(t.output)}</div>`:''}
 ${artifact?`<a class="file-download" href="${esc(artifact.url)}" download="${esc(artifact.filename)}">${icon('file')}<span>${esc(artifact.name)}<small>下载本地生成的交付文件</small></span>${icon('download','download-icon')}</a>`:''}
 ${taskDone(t)?renderOfficeExports(t):''}
 ${renderTaskMail(t)}
 </div><div class="task-disclaimer"><b>${t.mode==='api'?'API 模式':'演示环境'}</b> · ${t.mode==='api'?'本任务使用创建时配置的模型服务':'本任务由确定性本地流程执行，不调用真实大模型'} · ${t.mode==='api'?'真实邮件逐封审批；结果不确定时不重发':'演示邮件仅生成本地草稿'}</div></article>`;
}
function renderTaskMail(t){const mail=array(state.mail?.drafts||state.mail).filter(m=>String(m.taskId)===String(t.id));return mail.map(m=>`<div class="browser-panel"><div class="browser-panel-toolbar">${icon('mail')}本地邮件草稿 <span class="mode-label">未发送</span></div><div style="padding:17px"><h3 class="detail-label">${esc(m.subject||m.title||'邮件草稿')}</h3>${m.to?`<p class="detail-meta">收件人：${esc(str(m.to))}</p>`:''}<div class="output-block" style="margin-bottom:0">${esc(m.body||m.content||'')}</div></div></div>`).join('');}
function renderBrowser(t){const sid=encodeURIComponent(t.browserSessionId);const manual=t.browserSession?.status==='manual';const canControl=t.status==='awaiting_approval';return `<section class="browser-panel"><div class="browser-panel-toolbar">${icon('browser')}浏览器执行现场 · ${manual?'人工接管中':'智能体控制'}<div class="button-row"><button class="secondary-button small-button" data-action="browser-takeover" data-id="${esc(t.browserSessionId)}" ${!canControl?'disabled title="仅等待审批时可接管"':''}>${manual?'打开接管窗口':'手动接管'}</button><button class="secondary-button small-button" data-action="browser-resume" data-id="${esc(t.browserSessionId)}" ${!canControl||!manual?'disabled':''}>恢复执行</button></div></div><img class="browser-preview" src="/api/browser/${sid}/screenshot?t=${encodeURIComponent(t.updatedAt||'latest')}" alt="当前模拟 OA 浏览器画面" data-browser-image><div class="browser-instructions">等待审批时可手动接管，检查或修改本地模拟 OA；完成后归还控制权，再确认原计划。<br><button class="text-link" data-action="view-browser" data-id="${esc(t.browserSessionId)}" style="padding:4px 0">在工作台内查看模拟 OA ↗</button> · 仅连接本地演示系统。</div></section>`;}

function agentModelLabel(a){return a.modelConfig?.inherit===false?`独立模型 · ${a.modelConfig.model}`:'继承工作台模型';}
function renderAgents(){return pageHeading('YOUR TEAM','懂分工，也懂配合','为每个角色配置模型、做事风格与工具权限。',`<button class="primary-button" data-action="add-agent">${icon('plus')}创建智能体</button>`)+`<div class="info-banner">${icon('shield')}角色可以使用不同的模型与专属知识。这里隔离的是模型检索上下文，不是多用户账户；你仍可管理全部本地资料。</div><div class="cards-grid">${state.agents.map((a,i)=>`<article class="agent-card"><div class="agent-card-header"><div class="agent-avatar color-${i%4}">${esc((a.name||'助').slice(0,1))}</div><div><h3>${esc(a.name)}</h3><span class="agent-role">${esc(a.role||'办公协作助手')}</span></div></div><p>${esc(a.personality||'尚未设置工作风格')}</p><div class="agent-model-label ${a.modelConfig?.inherit===false?'independent':''}">${icon('spark')}<span>${esc(agentModelLabel(a))}</span>${a.modelConfig?.inherit===false?`<small>${a.hasApiKey?'密钥已配置':'需配置密钥'}</small>`:''}</div><div class="permission-tags">${array(a.permissions).map(p=>`<span class="permission-tag">${esc(permissions[p]?.[0]||p)}</span>`).join('')||'<span class="permission-tag">未授予工具权限</span>'}</div><div class="agent-card-footer"><span class="status-text" style="${a.enabled===false?'color:#a8b29d':''}"><i></i>${a.enabled===false?'已停用':'可执行任务'}</span><button class="secondary-button small-button" data-action="edit-agent" data-id="${esc(a.id)}">配置智能体</button></div></article>`).join('')}<button class="create-agent-card" data-action="add-agent">${icon('plus')}<span>添加一位新伙伴</span><small>独立模型、工作风格与工具权限</small></button></div>`;}
function renderKnowledge(){return pageHeading('KNOWLEDGE & MEMORY','把经验，放在合适的位置','共享资料协同使用，角色私有资料按模型检索权限隔离。',`<button class="primary-button" data-action="add-memory">${icon('plus')}添加知识</button>`)+`<div class="info-banner">${icon('knowledge')}你可以查看和管理全部本地知识。「角色私有」仅供所属角色直接检索；读取私有知识后的任务不能再向其他角色转交上下文；可新开只用共享资料的任务。这不是多用户账户权限隔离。</div>`+(state.memories.length?`<div class="cards-grid">${state.memories.map(m=>`<article class="memory-card"><div class="memory-scope ${m.scope==='agent'?'private':''}">${icon(m.scope==='agent'?'lock':'knowledge')}${m.scope==='agent'?`角色私有 · ${esc(getAgent(m.ownerAgentId)?.name||'所属角色')}`:'工作空间共享'}</div><h3>${icon('file')}${esc(m.title||'未命名知识')}</h3><p>${esc(m.content||'')}</p><div class="memory-footer"><span>来源：${esc(m.source||'手动添加')}</span><time>${date(m.createdAt||m.updatedAt)}</time></div></article>`).join('')}</div>`:empty('knowledge','还没有知识资料','添加工作背景或制度要点，并选择共享范围与所属角色。',`<button class="primary-button" data-action="add-memory">${icon('plus')}添加第一条知识</button>`));}
function renderAgentModelForm(a={}){const inherit=a.modelConfig?.inherit!==false;return `<section class="role-model-section"><h3>${icon('spark')}这个角色使用的模型</h3><label class="check-row"><input id="agent-inherit-model" type="checkbox" name="inheritModel" ${inherit?'checked':''}><span>继承工作台的全局模型<small>在 API 模式下生效；本地演示仍使用确定性流程。</small></span></label><div id="agent-own-model" ${inherit?'hidden':''}><div class="form-field"><label for="agent-endpoint">独立 API 端点</label><input id="agent-endpoint" name="roleEndpoint" type="url" value="${esc(a.modelConfig?.endpoint||state.settings.endpoint||'https://api.openai.com/v1')}" placeholder="https://api.openai.com/v1" ${inherit?'disabled':'required'}><small>仅 HTTPS。任务和该角色有权检索的资料会发送到此服务商。</small></div><div class="form-row"><div class="form-field"><label for="agent-model">模型名称</label><input id="agent-model" name="roleModel" value="${esc(a.modelConfig?.model||'')}" placeholder="服务商支持的模型名称" maxlength="200" ${inherit?'disabled':'required'}></div><div class="form-field"><label for="agent-api-key">此角色的 API Key</label><input id="agent-api-key" name="roleApiKey" type="password" autocomplete="off" placeholder="${a.hasApiKey?'已配置；留空保留当前密钥':'尚未配置独立密钥'}" ${inherit?'disabled':''}><small>留空不会覆盖现有密钥。${credentialStorageHelp()}</small></div></div>${a.hasApiKey?`<label class="check-row"><input type="checkbox" name="clearRoleApiKey" ${inherit?'disabled':''}><span>清除当前角色密钥<small>保存后生效，不影响其他角色。</small></span></label>`:''}<div class="permission-warning">更换服务商域名或恢复全局继承会清除当前角色密钥。读取私有知识后，该任务不能转交其他角色；需要时新开只用共享资料的任务。</div></div></section>`;}
function renderMemoryScopeFields(){return `<div class="form-row"><div class="form-field"><label for="memory-scope">可见范围</label><select id="memory-scope" name="scope"><option value="workspace">工作空间共享</option><option value="agent" ${!state.agents.length?'disabled':''}>仅指定角色使用</option></select></div><div class="form-field" id="memory-owner-field" hidden><label for="memory-owner">所属智能体</label><select id="memory-owner" name="ownerAgentId" disabled>${state.agents.map(a=>`<option value="${esc(a.id)}">${esc(a.name)} · ${esc(a.role)}</option>`).join('')}</select></div></div><p class="scope-help">共享知识可被获授权角色读取；读取私有知识后的任务不能再向其他角色转交上下文；可新开只用共享资料的任务。你作为本地管理者仍能查看全部内容。</p>`;}

function renderAudit(){return pageHeading('ACTIVITY LOG','看清过程，才能放心托付','任务、审批与配置变更都留有记录，可按时间追溯。',`<button class="secondary-button" data-action="refresh">${icon('refresh')}刷新记录</button>`)+(state.audit.length?`<div class="audit-list">${state.audit.slice(0,150).map(a=>`<article class="audit-item"><div class="audit-symbol">${icon(/approv|批准|拒绝/.test(a.action)?'shield':/agent|智能体/.test(a.action)?'agents':/memory|知识/.test(a.action)?'knowledge':'audit')}</div><div><h3>${esc(auditLabels[a.action]||a.action||a.type||'操作记录')}</h3><p>${esc(str(a.detail||a.message||''))}</p>${a.taskId?`<button class="text-link" data-task="${esc(a.taskId)}">查看关联任务 ↗</button>`:''}</div><time>${date(a.at||a.createdAt,true)}</time></article>`).join('')}</div>`:empty('audit','还没有操作记录','发起任务、添加知识或保存设置后，相应记录会显示在这里。'));}

const weekDays=['日','一','二','三','四','五','六'];
function localTimezone(){return Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';}
function scheduleDate(value,timezone){if(!value)return '尚未运行';try{return new Intl.DateTimeFormat('zh-CN',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value));}catch{return '时间不可用';}}
function scheduleSummary(schedule){const r=schedule.recurrence||{};if(r.type==='interval')return `每 ${r.intervalMinutes} 分钟`;if(r.type==='weekly')return `每周${array(r.daysOfWeek).map(d=>weekDays[d]).join('、')} ${r.time||''}`;return `每天 ${r.time||''}`;}
function scheduleBadge(status){const values={active:['已启用','completed'],paused:['已暂停','approval'],cancelled:['已取消','cancelled']};const [label,cls]=values[status]||['状态未知','approval'];return `<span class="badge ${cls}">${label}</span>`;}
function renderSchedules(){
 const schedules=array(state.schedules),active=schedules.filter(s=>s.status==='active').length;
 return pageHeading('RECURRING TASKS','把例行工作，排进日程','按明确的时区与频率，持续创建可追踪的本地任务。',`<button class="primary-button" data-action="add-schedule">${icon('plus')}新建周期任务</button>`)+
 `<div class="info-banner schedule-notice">${icon('clock')}<div><strong>本机调度 · ${active} 项已启用</strong>${!heartbeatOn()?'<p class="schedule-heartbeat-warning">主动检查已关闭，周期任务暂不触发。请开启左侧「主动检查」后继续调度。</p>':''}<p>计划会保存在本地，应用或本地服务运行时才会执行。关闭或休眠期间不会执行；恢复后错过的多次执行合并为最多一次，不连续补跑。任务按运行时的工作台模式与角色权限执行；API 模式会发送任务及所需资料到配置的模型服务，可能计费。邮件发送与网页输入仍逐次审批。</p></div></div>`+
 (schedules.length?`<div class="schedule-grid">${schedules.map(s=>{const busy=scheduleBusy.has(s.id),cancelled=s.status==='cancelled';return `<article class="schedule-card" data-schedule-id="${esc(s.id)}"><div class="schedule-top">${scheduleBadge(s.status)}<span>${esc(scheduleSummary(s))}</span></div><h2>${esc(s.title)}</h2><p class="schedule-prompt">${esc(s.prompt)}</p><div class="schedule-meta"><span>${icon('agents')}${esc(getAgent(s.agentId)?.name||'自动选择助手')} · 预算 ${esc(s.budget)} 步</span><span>${icon('clock')}时区 ${esc(s.timezone)}</span></div><dl class="schedule-timing"><dt>下次执行</dt><dd>${s.status==='active'?(s.nextRunAt?esc(scheduleDate(s.nextRunAt,s.timezone)):'等待调度'):s.status==='paused'?'恢复后重新计算':'不再创建任务'}</dd><dt>上次执行</dt><dd>${esc(scheduleDate(s.lastRunAt,s.timezone))}${s.lastTaskId?` <button class="text-link" data-task="${esc(s.lastTaskId)}">查看任务 ↗</button>`:''}</dd></dl>${s.lastError?`<p class="schedule-error">${icon('alert')}${esc(s.lastError)}</p>`:''}<div class="schedule-actions">${!cancelled?`<button class="secondary-button small-button" data-action="edit-schedule" data-id="${esc(s.id)}" ${busy?'disabled':''}>编辑</button><button class="secondary-button small-button" data-action="schedule-${s.status==='paused'?'resume':'pause'}" data-id="${esc(s.id)}" ${busy?'disabled':''}>${icon(s.status==='paused'?'refresh':'pause')}${s.status==='paused'?'恢复':'暂停'}</button><button class="text-link danger-link" data-action="cancel-schedule" data-id="${esc(s.id)}" ${busy?'disabled':''}>取消计划</button>`:'<span class="schedule-closed">记录已保留 · 已创建的任务不受影响</span>'}</div></article>`;}).join('')}</div>`:empty('clock','还没有周期任务','把每天整理资料、每周生成报告这样的例行工作，设置为本地周期任务。',`<button class="primary-button" data-action="add-schedule">${icon('plus')}创建第一个计划</button>`));
}
function renderScheduleForm(schedule){
 const s=schedule||{},r=s.recurrence||{type:'daily',time:'09:00'},timezone=s.timezone||localTimezone();
 const agents=state.agents.filter(a=>a.enabled!==false||a.id===s.agentId);
 return `<p class="modal-subtitle">任务仅在本机应用或服务运行、且主动检查开启时创建。按运行时的工作台模式与角色权限执行；API 模式会自动把任务和所需资料发送到配置的模型服务，可能计费。时间按下面的 IANA 时区解释。</p><form id="schedule-form" data-id="${esc(s.id||'')}"><div class="form-field"><label for="schedule-title">计划名称</label><input id="schedule-title" name="title" required maxlength="200" value="${esc(s.title||'')}" placeholder="例如：每周养护工作汇总"></div><div class="form-field"><label for="schedule-prompt">每次要执行的任务</label><textarea id="schedule-prompt" name="prompt" required maxlength="12000" placeholder="例如：整理本地养护待办，注明资料来源并生成周报">${esc(s.prompt||'')}</textarea></div><div class="form-row"><div class="form-field"><label for="schedule-agent">执行智能体</label><select id="schedule-agent" name="agentId"><option value="">默认协调助手</option>${agents.map(a=>`<option value="${esc(a.id)}" ${a.id===s.agentId?'selected':''}>${esc(a.name)}${a.enabled===false?'（已停用，请更换）':''}</option>`).join('')}</select></div><div class="form-field"><label for="schedule-budget">每次执行预算（步骤数）</label><input id="schedule-budget" name="budget" type="number" min="1" max="100" step="1" required value="${Number(s.budget)||Number(state.settings.budget)||20}"></div></div><div class="form-row"><div class="form-field"><label for="schedule-recurrence">执行频率</label><select id="schedule-recurrence" name="recurrenceType"><option value="daily" ${r.type==='daily'?'selected':''}>每天</option><option value="weekly" ${r.type==='weekly'?'selected':''}>每周</option><option value="interval" ${r.type==='interval'?'selected':''}>固定分钟间隔</option></select></div><div class="form-field"><label for="schedule-timezone">IANA 时区</label><input id="schedule-timezone" name="timezone" required maxlength="100" value="${esc(timezone)}" placeholder="例如：Asia/Shanghai" list="schedule-timezones"><datalist id="schedule-timezones"><option value="Asia/Shanghai"><option value="Asia/Hong_Kong"><option value="Asia/Tokyo"><option value="America/New_York"><option value="Europe/London"><option value="UTC"></datalist><small>首次默认此设备时区，可明确修改。</small></div></div><div class="form-field" id="schedule-time-field" ${r.type==='interval'?'hidden':''}><label for="schedule-time">当地执行时间</label><input id="schedule-time" name="time" type="time" value="${esc(r.time||'09:00')}" ${r.type==='interval'?'disabled':'required'}><small>按上方时区的当地时间执行；切换时区不会换算输入值。夏令时跳过不存在的时间，重复时间只执行较早的一次。</small></div><div class="form-field" id="schedule-interval-field" ${r.type!=='interval'?'hidden':''}><label for="schedule-interval">间隔分钟数</label><input id="schedule-interval" name="intervalMinutes" type="number" min="1" max="525600" step="1" value="${Number(r.intervalMinutes)||60}" ${r.type==='interval'?'required':'disabled'}><small>新建计划默认在一个完整间隔后首次执行；编辑时保留原始起点，重新计算下次执行。</small></div><fieldset class="schedule-weekdays" id="schedule-days-field" ${r.type!=='weekly'?'hidden':''}><legend>每周执行日（至少一天）</legend>${[1,2,3,4,5,6,0].map(d=>`<label class="check-row"><input type="checkbox" name="daysOfWeek" value="${d}" ${array(r.daysOfWeek||[1]).includes(d)?'checked':''} ${r.type!=='weekly'?'disabled':''}><span>周${weekDays[d]}</span></label>`).join('')}</fieldset><p class="permission-warning">保存计划即同意按上述周期创建任务及相应的模型调用。邮件发送与网页输入仍逐次审批。错过的执行合并为最多一次；暂停或取消计划不会停止已创建任务，请在任务中心单独处理。</p><div class="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary-button" data-action="close-modal">取消</button><button type="submit" class="primary-button">${s.id?'保存计划':'创建计划'}</button></div></form>`;
}
function syncScheduleFields(){const type=$('#schedule-recurrence')?.value;if(!type)return;for(const [id,enabled] of [['schedule-time-field',type!=='interval'],['schedule-interval-field',type==='interval'],['schedule-days-field',type==='weekly']]){const field=$('#'+id);field.hidden=!enabled;field.querySelectorAll('input').forEach(input=>{input.disabled=!enabled;if(input.type!=='checkbox')input.required=enabled;});}}
async function scheduleAction(name,id,el){if(scheduleBusy.has(id))return;const command=name.replace('schedule-','');if(!['pause','resume','cancel'].includes(command))return;scheduleBusy.add(id);if(el)el.disabled=true;try{await post('/api/schedules/'+encodeURIComponent(id)+'/'+command);if(modal?.kind==='schedule-cancel'&&modal.id===id)closeModal();await loadState(true);toast(command==='pause'?'计划已暂停；已创建的任务保持原状':command==='resume'?'计划已恢复，请核对下次执行时间':'计划已取消；历史任务与记录已保留');}catch(error){const node=$('#modal-root .modal-error');if(node)node.textContent=error.message;toast(error.message,true);}finally{scheduleBusy.delete(id);if(view==='schedules')render(true);if(el&&document.contains(el))el.disabled=false;}}
function renderOfficeExports(task){const owner=getAgent(task.agentId),canExport=owner?.enabled!==false&&array(owner?.permissions).includes('workspace.write');const saved=Object.fromEntries(array(task.exports).filter(a=>['docx','xlsx'].includes(a.format)&&typeof a.url==='string'&&/^\/api\/artifacts\/[^/?#]+$/.test(a.url)).map(a=>[a.format,{url:a.url,name:a.name||a.filename}]));const artifacts={...saved,...officeArtifacts.get(task.id)};return `<section class="office-exports"><h3 class="detail-label">Office 交付文件 </h3><p>根据已完成的任务结果生成本地 Word / Excel 文件；导出不会重新执行任务。</p><div class="button-row">${['docx','xlsx'].map(format=>`<button class="secondary-button small-button" data-action="export-task" data-id="${esc(task.id)}" data-format="${format}" ${!canExport||exportBusy.has(task.id+':'+format)?'disabled':''}>${icon('download')}${exportBusy.has(task.id+':'+format)?'正在生成…':format==='docx'?'导出 Word (.docx)':'导出 Excel (.xlsx)'}</button>`).join('')}</div>${!canExport?'<p class="permission-warning">执行角色需保持启用且拥有生成文件权限，才能创建新的导出文件。</p>':''}${Object.entries(artifacts).map(([format,a])=>`<a class="office-download" href="${esc(a.url)}" download="${esc(a.name)}">${icon('file')}${esc(a.name)} ${icon('download')}</a>`).join('')}</section>`;}
async function exportTask(id,format){const key=id+':'+format;if(exportBusy.has(key)||!['docx','xlsx'].includes(format))return;exportBusy.add(key);if(view==='tasks'||view==='chat'&&chatTaskId===id)render(true);try{const result=await post('/api/tasks/'+encodeURIComponent(id)+'/export',{format});const a=result.artifact||result;if(typeof a.url!=='string'||!/^\/api\/artifacts\/[^/?#]+$/.test(a.url))throw new Error('导出响应没有可用的本地下载地址');const artifact={url:a.url,name:a.name||a.filename||'任务结果.'+format};officeArtifacts.set(id,{...officeArtifacts.get(id),[format]:artifact});const link=document.createElement('a');link.href=artifact.url;link.download=artifact.name;link.hidden=true;document.body.append(link);link.click();link.remove();toast('已生成 '+format.toUpperCase()+'，可再次点击文件链接下载');}catch(error){toast(error.message,true);}finally{exportBusy.delete(key);if(view==='tasks'||view==='chat'&&chatTaskId===id)render(true);}}
function credentialStorageHelp(){return state.desktop?.available?'默认只保存在当前进程内存中。可在设置下方单独确认，使用系统安全存储保存一份凭据。':'仅保存在服务进程内存中，重启后需重新输入。';}
function renderDesktopSettings(){
 const d=state.desktop;if(!d?.available)return '';const vault=d.credentialVault||{},secure=!!vault.available;
 return `<div id="desktop-settings"><section class="form-panel"><h2>${icon('browser')}桌面运行 </h2><p class="form-panel-description">后台运行由这台电脑承担，不是云服务，也不等于开机自启。</p><form id="desktop-preferences-form"><label class="check-row"><input id="desktop-background" type="checkbox" name="backgroundEnabled" ${d.backgroundEnabled?'checked':''} ${!d.trayAvailable?'disabled':''}><span>关窗后留在系统托盘运行<small>启用后，关闭窗口会隐藏到托盘；从托盘退出才停止服务。关机、休眠或退出应用时任务不会执行。</small></span></label>${!d.trayAvailable?'<p class="permission-warning">当前环境没有可用的系统托盘，无法启用关窗后台运行。</p>':''}<div class="form-actions"><button class="secondary-button" type="submit" ${!d.trayAvailable?'disabled':''}>保存桌面偏好</button></div><div class="modal-error" role="alert"></div></form></section><section class="form-panel"><h2>${icon('lock')}凭据安全存储</h2>${vault.restoreError===true?'<div class="permission-warning" role="alert">已保存的凭据未能恢复，本次启动未导入该快照。请重新输入凭据；确认内容后可重新加密保存。不会退回明文存储。</div>':''}<div class="security-state">当前状态<span>${vault.stored?'已有加密保存的凭据':'尚未保存凭据'}</span></div><div class="security-state">系统存储后端<span>${esc(vault.backend||'未检测到')}</span></div><p class="form-panel-description">保存当前全局模型 Key、独立角色模型 Key 和 IMAP / SMTP 邮件凭据的一份加密快照，以便下次启动恢复。只有你明确选择才会保存；不会把密钥放入浏览器存储。</p>${!secure?`<div class="permission-warning">安全存储不可用，保存已禁用。${esc(vault.reason||'请先在受支持的桌面系统启用系统安全存储。')}不会退回明文存储。</div>`:''}<form id="desktop-credentials-form"><label class="check-row credential-consent"><input id="desktop-credential-consent" name="credentialConsent" type="checkbox" ${!secure?'disabled':''}><span>我同意将当前凭据加密保存到本机<small>用于之后启动恢复；更改凭据后需再次确认保存。仅在你信任并管理的电脑上启用。</small></span></label><div class="form-actions"><button id="desktop-save-credentials" class="primary-button" type="submit" disabled>${vault.stored?'更新加密凭据':'加密保存凭据'}</button>${vault.stored?'<button type="button" class="secondary-button" data-action="forget-credentials">删除已保存的凭据</button>':''}</div><div class="modal-error" role="alert"></div></form></section></div>`;
}
async function refreshDesktopSettings(){await loadState();const old=$('#desktop-settings');if(old)old.outerHTML=renderDesktopSettings();}

function renderSettings(){const s=state.settings;return pageHeading('SETTINGS','你的工作台，你来定义','配置模型连接，按需调整高级能力与运行边界。',`<button class="secondary-button" data-nav="agents">${icon('agents')}管理智能体与独立模型</button>`)+`<div class="settings-layout"><div><form id="settings-form"><section class="form-panel"><h2>${icon('spark')}执行模式</h2><p class="form-panel-description">此设置仅控制智能任务：演示无需密钥，API 模式连接所选模型。邮件与浏览器工作台仍可独立执行你批准的真实操作。</p><div class="mode-options"><label class="mode-option"><input type="radio" name="mode" value="demo" ${isDemo()?'checked':''}><span><strong>本地演示</strong><small>确定性流程 · 无模型费用<br>不调用真实大模型</small></span></label><label class="mode-option"><input type="radio" name="mode" value="api" ${!isDemo()?'checked':''}><span><strong>连接模型 API</strong><small>OpenAI 兼容接口<br>费用由模型服务商计费</small></span></label></div><div class="form-field"><label for="endpoint">API 端点</label><input id="endpoint" name="endpoint" type="url" placeholder="https://api.openai.com/v1" value="${esc(s.endpoint||'https://api.openai.com/v1')}"><small>仅接受 HTTPS 地址。使用前请确认该服务商可接收你的任务与知识内容。</small></div><div class="form-row"><div class="form-field"><label for="model">模型名称</label><input id="model" name="model" placeholder="输入服务商支持的模型名称" value="${esc(s.model||'')}"></div><div class="form-field"><label for="api-key">API Key</label><input id="api-key" name="apiKey" type="password" autocomplete="off" placeholder="${s.hasApiKey?'已配置，留空保留当前密钥':'输入模型服务的 API Key'}"><small>${credentialStorageHelp()}</small></div></div><div class="form-field"><label for="budget">每个任务的执行预算（步骤数）</label><input id="budget" name="budget" type="number" min="1" max="100" value="${Number(s.budget)||20}" required><small>限制单个任务的执行步数。达到预算后停止继续执行。</small></div><div class="form-actions"><button type="submit" class="primary-button">保存配置</button><button type="button" class="secondary-button" data-action="test-api">${icon('link')}测试已保存的连接</button></div><div id="settings-status" class="form-status" role="status"></div><button type="button" class="text-link diagnostic-copy" data-action="copy-connection-diagnostic" ${connectionDiagnostic?'':'hidden'}>${icon('copy')}复制连接诊断（不含密钥）</button></section></form>${renderDesktopSettings()}<section class="form-panel"><h2>${icon('shield')}本地安全边界</h2><p class="form-panel-description">关键操作保持可见，外部系统操作不静默发生。</p><div class="security-state">网页填写与点击<span>确切内容需要审批</span></div><div class="security-state">邮件发送<span>演示仅草稿；真实发送逐封审批</span></div><div class="security-state">API 密钥存储<span>${state.desktop?.credentialVault?.stored?'已选择系统加密存储':'默认仅进程内存'}</span></div><div class="security-state">任务与知识<span>保存在本地工作空间</span></div></section></div><aside class="settings-note"><h3>先体验，再接入</h3><p>第一次使用，建议从本地演示开始。无需任何账户或密钥，即可测试：</p><ul><li>读取演示养护资料与生成周报</li><li>在模拟 OA 中填写巡查安排</li><li>审批网页提交并查看执行现场</li><li>保存邮件草稿与设置提醒</li></ul><div class="mini-divider"></div><h3>连接前，请了解</h3><p>API 模式会将任务描述和执行所需的资料发送到你配置的模型服务。请遵守单位的数据管理要求，不输入敏感、涉密或未经授权共享的信息。</p><p>更换模型端点前，请核对服务商地址。密钥不会出现在操作日志和界面返回数据中。</p></aside></div>`;}

function mailAccount(){return array(state.mailAccounts).find(a=>a.accountId===mailAccountId)||array(state.mailAccounts)[0]||null;}
function mailBadge(status){const labels={draft:['草稿','queued'],pending_approval:['待发送审批','approval'],approved:['准备发送','running'],sending:['正在发送','running'],sent:['服务器已接受','completed'],unknown:['结果不确定','approval'],failed:['发送失败','failed'],rejected:['已拒绝','cancelled'],cancelled:['已取消','cancelled']};const [label,cls]=labels[status]||[status||'草稿','queued'];return `<span class="badge ${cls}">${esc(label)}</span>`;}
function mailProvider(account){if(!account?.smtp)return '未配置 SMTP';return `${account.smtp.host}:${account.smtp.port} · ${account.smtp.secure?'隐式 TLS':'强制 STARTTLS'}`;}
function renderMail(){
 const account=mailAccount();if(account)mailAccountId=account.accountId;
 const inbox=array(state.realInbox).filter(m=>!account||m.accountId===account.accountId),outbox=array(state.mailOutbox).filter(m=>!account||m.accountId===account.accountId);
 const selected=outbox.find(m=>m.id===selectedMailId)||outbox[0],hasImap=!!(account?.imap&&account?.hasCredentials?.imap),hasSmtp=!!account?.smtp;
 let content='';
 if(!account)content=empty('mail','先配置一个邮箱账户','支持 IMAP 收件与 SMTP 发件。未配置时，不会读取邮箱，也不会发送任何邮件。',`<button class="primary-button" data-action="mail-config">${icon('settings')}配置真实邮箱</button>`);
 else if(mailTab==='inbox')content=inbox.length?`<div class="mail-inbox-list">${inbox.map(m=>`<button class="mail-inbox-item" data-action="mail-message" data-id="${esc(m.id)}"><span class="mail-message-icon">${icon('mail')}</span><span><strong>${esc(m.subject||'（无主题）')}</strong><span class="mail-from">${esc(m.from||'未提供发件人')}</span><span class="mail-snippet">${esc((m.text||'').slice(0,160))}</span></span><time>${date(m.date||m.readAt)}${m.truncated?'<small>正文已截断</small>':''}</time></button>`).join('')}</div>`:empty('mail',hasImap?'还没有读取邮件':'需要补全 IMAP 凭据',hasImap?'点击「读取收件箱」拉取真实数据。不会自动轮询邮箱。':'保存账户后，重新输入仅保留在内存中的 IMAP 凭据，才可读取收件箱。');
 else content=outbox.length?`<div class="mail-outbox-workspace"><div class="mail-outbox-list">${outbox.map(m=>`<button class="task-card ${selected?.id===m.id?'selected':''}" data-mail-draft="${esc(m.id)}"><div class="task-card-top">${mailBadge(m.status)}<time>${date(m.createdAt)}</time></div><h3>${esc(m.subject)}</h3><span class="task-card-agent">${esc(array(m.to).join(', '))}</span></button>`).join('')}</div>${selected?renderMailDraft(selected,account):''}</div>`:empty('file','先把邮件写成草稿','草稿仅保存在本地。提交审批后，只有你批准了确切内容，才会尝试发送。',`<button class="primary-button" data-action="mail-compose" ${!hasSmtp?'disabled':''}>${icon('plus')}新建邮件草稿</button>`);
 return pageHeading('MAIL WORKSPACE','邮件往来，先看清再发送','按需读取真实收件箱；每封外发邮件，都需要明确审批。',`<div class="button-row"><button class="secondary-button" data-action="mail-config">${icon('settings')}${account?'账户配置':'连接邮箱'}</button><button class="primary-button" data-action="mail-compose" ${!hasSmtp?'disabled title="请先配置 SMTP 账户"':''}>${icon('plus')}新建草稿</button></div>`)+`<div class="mail-account-panel"><span class="mail-account-icon">${icon('mail')}</span><div><strong>${account?esc(account.from):'尚未连接真实邮箱'}</strong><p>${account?`${esc(mailProvider(account))} · 凭据${account.hasCredentials?.smtp?'已配置':'需重新输入'}`:'此页没有演示收件箱。配置账户后才能读取真实邮件或准备外发。'}</p></div>${array(state.mailAccounts).length>1?`<select id="mail-account-select" aria-label="选择邮件账户">${state.mailAccounts.map(a=>`<option value="${esc(a.accountId)}" ${a.accountId===account.accountId?'selected':''}>${esc(a.from)}</option>`).join('')}</select>`:''}<button class="text-link" data-action="mail-new-account">添加账户 ＋</button></div><div class="info-banner">${icon('shield')}${credentialStorageHelp()}此页仅管理真实邮箱适配器；对话中的演示邮件仍保留在对应任务里。</div><div class="view-toolbar"><div class="tabs"><button class="tab ${mailTab==='inbox'?'active':''}" data-mail-tab="inbox">真实收件箱 ${inbox.length}</button><button class="tab ${mailTab==='outbox'?'active':''}" data-mail-tab="outbox">草稿与发送 ${outbox.length}</button></div><button class="secondary-button" data-action="mail-fetch" ${!hasImap||mailBusy.has('fetch')?'disabled':''}>${icon('refresh')}${mailBusy.has('fetch')?'正在读取…':'读取收件箱'}</button></div>${content}`;
}
function renderMailDraft(d,account){const approval=array(state.mailApprovals).find(a=>a.draftId===d.id&&a.status==='pending');const canRequest=['draft','failed','rejected'].includes(d.status)&&!d.dataStarted;const busy=mailBusy.has(d.id);return `<article class="task-detail mail-draft-detail"><div class="detail-top"><div class="detail-topline">${mailBadge(d.status)}<span class="code-label">尝试 ${Number(d.attempts)||0} 次</span></div><h2>${esc(d.subject)}</h2><div class="mail-addresses"><p><span>发件人</span>${esc(d.from)}</p><p><span>收件人</span>${esc(array(d.to).join(', '))}</p><p><span>服务商</span>${esc(mailProvider({smtp:d.transport||account?.smtp}))}</p></div></div><div class="detail-body">${d.status==='unknown'?`<div class="mail-risk-warning">${icon('alert')}<div><strong>可能已经发送，请勿重试</strong><p>服务器结果未能确认。请自行核对服务商的已发送记录或向收件人确认；本客户端不会自动重试此邮件。</p></div></div>`:''}${d.partial?'<div class="mail-risk-warning">部分收件人可能被服务器拒绝，请核对下方接受与拒绝名单。</div>':''}${d.error?`<div class="mail-error-note">${esc(d.error)}</div>`:''}<h3 class="detail-label">纯文本正文</h3><div class="output-block">${esc(d.text)}</div>${array(d.accepted).length?`<p class="mail-delivery-detail">服务器接受：${esc(d.accepted.join(', '))}</p>`:''}${array(d.rejected).length?`<p class="mail-delivery-detail">服务器拒绝：${esc(d.rejected.join(', '))}</p>`:''}<div class="button-row">${(canRequest||d.status==='pending_approval')?`<button class="secondary-button" data-action="mail-edit" data-id="${esc(d.id)}" ${busy?'disabled':''}>编辑草稿</button>`:''}${canRequest?`<button class="primary-button" data-action="mail-request-send" data-id="${esc(d.id)}" ${busy?'disabled':''}>${icon('shield')}提交发送审批</button>`:''}${approval?`<button class="primary-button" data-action="mail-review" data-id="${esc(approval.id)}">${icon('shield')}查看完整审批内容</button>`:''}${['approved','sending','pending_approval'].includes(d.status)?`<button class="secondary-button" data-action="mail-cancel" data-id="${esc(d.id)}" ${mailBusy.has('cancel:'+d.id)?'disabled':''}>请求停止本次发送</button>`:''}</div>${['approved','sending'].includes(d.status)?'<p class="mail-delivery-detail">停止请求不能撤回已经交给服务器的邮件。若已开始传输，结果可能变为「不确定」。</p>':''}</div><div class="task-disclaimer">SMTP 成功只表示服务器接受邮件，不保证对方收件箱已收到。发送状态不确定时不提供重试。</div></article>`;}
function renderMailConfigForm(account){const isNew=!account;const a=account||{accountId:state.mailAccounts?.length?'':'main',from:'',imap:{secure:true,port:993},smtp:{secure:true,port:465}};return `<p class="modal-subtitle">保存只校验连接配置，不会读取或发送邮件。${credentialStorageHelp()}</p><form id="mail-config-form"><div class="form-row"><div class="form-field"><label for="mail-account-id">账户标识</label><input id="mail-account-id" name="accountId" value="${esc(a.accountId)}" placeholder="例如：main" pattern="(?:[A-Za-z0-9_]|-){1,80}" ${isNew?'':'readonly'} required></div><div class="form-field"><label for="mail-from">发件人地址</label><input id="mail-from" name="from" type="email" value="${esc(a.from)}" required placeholder="office@example.com"></div></div>${['imap','smtp'].map(protocol=>{const conf=a[protocol]||{secure:true,port:protocol==='imap'?993:465};return `<section class="mail-protocol-section"><h3>${protocol==='imap'?'IMAP 收件配置':'SMTP 发件配置'}</h3><div class="form-row"><div class="form-field"><label for="${protocol}-host">服务器主机名</label><input id="${protocol}-host" name="${protocol}Host" value="${esc(conf.host||'')}" placeholder="${protocol}.example.com" required></div><div class="form-field"><label for="${protocol}-tls">传输加密</label><select id="${protocol}-tls" name="${protocol}Secure" data-mail-protocol="${protocol}"><option value="true" ${conf.secure!==false?'selected':''}>隐式 TLS</option><option value="false" ${conf.secure===false?'selected':''}>强制 STARTTLS</option></select></div></div><div class="form-row"><div class="form-field"><label for="${protocol}-port">端口</label><input id="${protocol}-port" name="${protocol}Port" type="number" value="${Number(conf.port)||(protocol==='imap'?993:465)}" required min="1" max="65535"></div><div class="form-field"><label for="${protocol}-user">登录用户名</label><input id="${protocol}-user" name="${protocol}User" value="${esc(conf.user||'')}" autocomplete="off" required></div></div><div class="form-field"><label for="${protocol}-password">密码 / 应用专用密码</label><input id="${protocol}-password" name="${protocol}Password" type="password" autocomplete="off" placeholder="${a.hasCredentials?.[protocol]?'已配置；同一端点留空保留':'请由账户本人输入'}"><small>留空仅会保留同一服务器、端口和用户名的当前内存凭据；修改这些字段后需重新输入。</small></div></section>`;}).join('')}<div class="permission-warning">只连接公开网络邮件服务器，始终要求 TLS 与证书校验。请确认服务商允许 IMAP / SMTP，并遵守单位信息管理要求。</div><div class="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary-button" data-action="close-modal">取消</button><button type="submit" class="primary-button">保存账户配置</button></div></form>`;}
function renderMailComposeForm(draft=null){const account=mailAccount();return `<p class="modal-subtitle">${draft?'编辑会使旧的待发送审批失效。':''}此步骤只保存本地草稿，不会发送。发送前会再次展示确切收件人、主题、正文与邮件服务商供你审批。</p><form id="mail-draft-form" data-id="${esc(draft?.id||'')}"><div class="form-field"><label>发送账户</label><select name="accountId" ${draft?'disabled':''}>${array(state.mailAccounts).filter(a=>a.smtp).map(a=>`<option value="${esc(a.accountId)}" ${a.accountId===(draft?.accountId||account?.accountId)?'selected':''}>${esc(a.from)} · ${esc(a.smtp.host)}</option>`).join('')}</select></div><div class="form-field"><label for="mail-to">收件人</label><input id="mail-to" name="to" value="${esc(array(draft?.to).join(', '))}" placeholder="recipient@example.com；多个地址用逗号分隔" required><small>最多 20 位收件人。请逐一核对完整邮箱地址。</small></div><div class="form-field"><label for="mail-subject">主题</label><input id="mail-subject" name="subject" value="${esc(draft?.subject||'')}" maxlength="300" required></div><div class="form-field"><label for="mail-text">纯文本正文</label><textarea id="mail-text" name="text" style="min-height:210px" maxlength="30000" required>${esc(draft?.text||'')}</textarea></div><div class="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary-button" data-action="close-modal">取消</button><button type="submit" class="primary-button">保存本地草稿</button></div></form>`;}
function renderMailApproval(a){const snap=a.snapshot||{};const account=array(state.mailAccounts).find(c=>c.accountId===snap.accountId);const provider=snap.transport||a.provider||snap.provider||account?.smtp;const description=provider?`${provider.host}:${provider.port} · ${provider.secure?'隐式 TLS':'强制 STARTTLS'}`:'服务商不可用';const allowed=!!account?.hasCredentials?.smtp;return `<div class="mail-risk-warning">${icon('shield')}<div><strong>批准后，将真实尝试发送这封邮件</strong><p>请核对下方完整内容。此审批仅适用于这一份内容快照和绑定的发送账户。</p></div></div><div class="mail-approval-snapshot"><dl><dt>发件人</dt><dd>${esc(snap.from)}</dd><dt>全部收件人</dt><dd>${esc(array(snap.to).join(', '))}</dd><dt>SMTP 服务商</dt><dd>${esc(description)}</dd><dt>认证用户名</dt><dd>${esc(provider?.user||'未提供')}</dd><dt>主题</dt><dd>${esc(snap.subject)}</dd></dl><h3 class="detail-label">完整纯文本正文</h3><div class="output-block">${esc(snap.text)}</div></div>${!allowed?'<div class="mail-error-note">该账户缺少当前进程的 SMTP 凭据。请关闭此窗口，补全账户配置后再审批。</div>':''}<p class="modal-subtitle">若网络在发送过程中中断，邮件可能已经交给服务器。结果不确定时不会自动重试。</p><div class="modal-error" role="alert"></div><div class="form-actions"><button class="secondary-button" data-action="mail-reject" data-id="${esc(a.id)}">拒绝本次发送</button><button class="primary-button" data-action="mail-approve" data-id="${esc(a.id)}" ${!allowed||mailBusy.has(a.draftId)?'disabled':''}>批准并真实发送</button></div>`;}

function controlledSession(){return array(state.controlledSessions).find(s=>s.id===selectedControlledId)||array(state.controlledSessions)[0]||null;}
function controlledBadge(status){const labels={opening:['正在打开','queued'],agent:['等待明确操作','completed'],taking_over:['正在交接','running'],manual:['人工接管','approval'],cancelled:['已关闭','cancelled'],interrupted:['已中断','cancelled'],error:['会话错误','failed'],pending:['待输入审批','approval'],executing:['执行中','running'],completed:['已执行','completed'],rejected:['已拒绝','cancelled'],stale:['已失效','cancelled'],expired:['已过期','cancelled'],unknown:['结果不确定','approval']};const [label,cls]=labels[status]||[status,'queued'];return `<span class="badge ${cls}">${esc(label)}</span>`;}
function controlledCancelled(result){const id=result?.session?.id||result?.sessionId;const latest=id?array(state.controlledSessions).find(s=>s.id===id):null;return result?.cancelled===true||['cancelled','interrupted'].includes(result?.session?.status)||['cancelled','interrupted'].includes(latest?.status);}
function controlledActive(s){return ['opening','agent','manual','taking_over'].includes(s.status);}
function renderControlled(){const session=controlledSession();if(session)selectedControlledId=session.id;return pageHeading('CONTROLLED BROWSER','网页操作，先看见再行动','每个目标独立会话，只按观察到的控件执行明确批准的输入。',`<button class="primary-button" data-action="cb-add-target">${icon('plus')}添加允许的目标</button>`)+`<div class="info-banner">${icon('shield')}仅支持明确配置的公网 HTTPS 目标。任何填写或点击都先审批；人工接管只允许普通文本控件，不支持密码、验证码、付款或文件输入。</div><section class="browser-targets">${array(state.browserTargets).map(t=>`<article class="browser-target-card"><div><strong>${esc(t.name)}</strong><span>${esc(t.startUrl)}</span><small>${t.enabled?'已启用':'已停用'} · ${array(t.allowedOrigins).length} 个允许的 origin${t.testOnly?' · 本地测试夹具':''}</small></div><div class="button-row"><button class="secondary-button small-button" data-action="cb-edit-target" data-id="${esc(t.id)}">配置</button><button class="primary-button small-button" data-action="cb-open" data-id="${esc(t.id)}" ${!t.enabled||controlledBusy.has('open')?'disabled':''}>打开隔离会话</button></div></article>`).join('')||empty('browser','尚未允许任何网站','先填写明确的起始网址与允许的 origin。保存目标只配置边界，不会打开网站。')}</section>${array(state.controlledSessions).length?`<div class="controlled-workspace"><div class="controlled-session-list">${state.controlledSessions.map(s=>`<button class="task-card ${s.id===session?.id?'selected':''}" data-controlled-session="${esc(s.id)}"><div class="task-card-top">${controlledBadge(s.status)}<time>${date(s.createdAt)}</time></div><h3>${esc(s.targetName||s.targetId)}</h3><span class="task-card-agent">${esc(s.title||'隔离浏览器会话')}</span></button>`).join('')}</div>${session?renderControlledSession(session):''}</div>`:''}`;}
function renderControlledSession(s){const obs=s.lastObservation,lease=controlledLeases.get(s.id),active=controlledActive(s),busy=controlledBusy.has(s.id);const approvals=array(state.browserApprovals).filter(a=>a.sessionId===s.id);const unknown=approvals.find(a=>a.status==='unknown');const controls=array(obs?.controls).filter(c=>!c.forbidden&&!c.sensitive&&c.enabled);const editable=active&&!!obs&&(!unknown||unknown.observationId!==obs.observationId)&&(s.status==='agent'||s.status==='manual'&&lease)&&!busy;const staged=controlledDrafts.get(s.id);const actions=staged?.observationId===obs?.observationId?staged.actions:[];
 return `<article class="task-detail controlled-detail"><div class="detail-top"><div class="detail-topline">${controlledBadge(s.status)}<div class="button-row"><button class="secondary-button small-button" data-action="cb-read" data-id="${esc(s.id)}" ${!active||busy?'disabled':''}>${icon('refresh')}重新读取</button>${s.status==='agent'?`<button class="secondary-button small-button" data-action="cb-takeover" data-id="${esc(s.id)}" ${busy?'disabled':''}>人工接管</button>`:''}${s.status==='manual'?`<button class="secondary-button small-button" data-action="cb-resume" data-id="${esc(s.id)}" ${!lease||busy?'disabled':''}>归还控制权</button>`:''}${active?`<button class="danger-button small-button" data-action="cb-cancel" data-id="${esc(s.id)}">关闭会话</button>`:''}</div></div><h2>${esc(s.title||s.targetName||'受控浏览器')}</h2><div class="controlled-url">${esc(s.url||s.startUrl)}</div></div><div class="detail-body">${s.error?`<div class="mail-error-note">${esc(s.error)}</div>`:''}${s.status==='manual'?`<div class="${lease?'info-banner':'mail-risk-warning'}">${icon('lock')}${lease?'此窗口持有人工独占控制权。下面的单个操作由你直接发起，不经智能体审批；敏感字段仍然禁用。':'此窗口没有当前人工租约，可能已刷新页面或由其他窗口接管。不能操作或归还；可关闭此会话后重新建立。'}</div>`:''}${unknown?`<div class="mail-risk-warning">${icon('alert')}部分输入可能已经生效，请先重新读取并核实页面。原批次不提供重试。</div>`:''}${s.screenshotReady?`<div class="controlled-shot"><img src="/api/controlled-browser/${encodeURIComponent(s.id)}/screenshot?v=${encodeURIComponent(obs?.observationId||'latest')}" alt="隔离浏览器当前画面" data-browser-image></div>`:''}${obs?`<details class="controlled-text"><summary>查看观察到的纯文本 · ${date(obs.observedAt)}</summary><div>${esc(obs.text||'页面未提供可读取文本')}</div></details><div class="section-heading"><h2>可操作控件</h2><span>${controls.length} 个普通控件</span></div>${controls.length?`<form id="controlled-action-form" data-id="${esc(s.id)}" data-observation-id="${esc(obs.observationId)}"><div class="form-row"><div class="form-field"><label for="cb-control">选择页面控件</label><select id="cb-control" name="controlId" ${!editable?'disabled':''}>${controls.map(c=>`<option value="${esc(c.controlId)}" data-fillable="${!!c.fillable}">${esc(c.controlId)} · ${esc(c.label)} (${esc(c.tag)})</option>`).join('')}</select></div><div class="form-field"><label for="cb-action-type">动作</label><select id="cb-action-type" name="type" ${!editable?'disabled':''}><option value="click">点击此控件</option><option value="fill" ${!controls[0]?.fillable?'disabled':''}>填写普通文本</option></select></div></div><div class="form-field" id="cb-value-field" hidden><label for="cb-value">将填写的确切文本</label><textarea id="cb-value" name="value" maxlength="4000" disabled placeholder="不输入密码、验证码、密钥或其他敏感凭据"></textarea></div><button type="submit" class="secondary-button" ${!editable?'disabled':''}>${s.status==='manual'?'由我执行这个动作':'加入待审批动作'}</button></form>`:'<div class="compact-empty">没有可操作的普通控件。密码、验证码与文件等敏感控件不会在此开放。</div>'}${s.status==='agent'&&actions.length?`<section class="controlled-staged"><h3>待审批动作 · 尚未输入页面</h3>${actions.map((a,i)=>`<div class="controlled-action-row"><span>${i+1}. ${a.type==='fill'?'填写':'点击'} ${esc(controls.find(c=>c.controlId===a.controlId)?.label||a.controlId)}${a.type==='fill'?`<small>${esc(a.value)}</small>`:''}</span><button class="text-link" data-action="cb-remove-action" data-id="${esc(s.id)}" data-index="${i}">移除</button></div>`).join('')}<div class="button-row"><button class="primary-button" data-action="cb-propose" data-id="${esc(s.id)}" ${busy?'disabled':''}>提交这 ${actions.length} 个动作审批</button><button class="secondary-button" data-action="cb-clear-actions" data-id="${esc(s.id)}">清空</button></div></section>`:''}`:'<div class="compact-empty">页面观察尚未就绪。请等待打开完成，或点击重新读取。</div>'}${approvals.length?`<section class="controlled-approvals"><div class="section-heading"><h2>输入审批记录</h2></div>${approvals.map(a=>`<div class="controlled-approval-row"><div>${controlledBadge(a.status)}<p>${a.actions.length} 个动作 · ${date(a.createdAt)}</p>${a.error?`<small>${esc(a.error)}</small>`:''}</div>${a.status==='pending'?`<button class="secondary-button small-button" data-action="cb-review" data-id="${esc(a.id)}">查看确切动作</button>`:''}</div>`).join('')}</section>`:''}${array(s.blockedRequests).length?`<details class="controlled-text"><summary>被阻止的网络请求 · ${s.blockedRequests.length} 条</summary><div>${s.blockedRequests.map(b=>`${esc(b.method)} ${esc(b.url)} · ${esc(b.reason)}`).join('\n')}</div></details>`:''}</div><div class="task-disclaimer">每个会话使用独立浏览器上下文；不导入本机登录状态，不执行任意脚本，刷新页面不会保存人工租约。</div></article>`;
}
function renderControlledTargetForm(target){return `<p class="modal-subtitle">仅允许公网 HTTPS 443。origin 必须精确填写协议与主机，如 https://example.com，不使用通配符。配置变更会关闭受影响的运行中会话，旧审批失效。</p><form id="controlled-target-form" data-id="${esc(target?.id||'')}"><div class="form-row"><div class="form-field"><label for="cb-target-id">目标标识</label><input id="cb-target-id" name="targetId" pattern="(?:[A-Za-z0-9_]|-){1,64}" value="${esc(target?.id||'')}" placeholder="例如：public-portal" ${target?'readonly':''} required></div><div class="form-field"><label for="cb-target-name">显示名称</label><input id="cb-target-name" name="name" value="${esc(target?.name||'')}" maxlength="80" required></div></div><div class="form-field"><label for="cb-start-url">起始网址</label><input id="cb-start-url" name="startUrl" type="url" value="${esc(target?.startUrl||'')}" placeholder="https://example.com/page" required></div><div class="form-field"><label for="cb-origins">允许的 origin（每行一个）</label><textarea id="cb-origins" name="allowedOrigins" placeholder="留空时仅允许起始网址所属 origin">${esc(array(target?.allowedOrigins).join('\n'))}</textarea><small>最多 8 个，必须包含起始网址的 origin。页面的其他域名资源将被阻止。</small></div><label class="check-row"><input type="checkbox" name="enabled" ${target?.enabled!==false?'checked':''}><span>启用这个目标</span></label><div class="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary-button" data-action="close-modal">取消</button><button type="submit" class="primary-button">保存目标边界</button></div></form>`;}
function renderControlledApproval(a){return `<div class="mail-risk-warning">${icon('shield')}批准后将按顺序执行下列确切动作。即使填写也可能触发网页自动保存；请核对目的地和每一项输入。</div><div class="mail-approval-snapshot"><dl><dt>目标页面</dt><dd>${esc(a.url)}</dd><dt>请求原因</dt><dd>${esc(a.reason||'由你在受控工作台中准备')}</dd><dt>有效期至</dt><dd>${date(a.expiresAt,true)}</dd></dl><ol class="controlled-exact-actions">${array(a.actions).map(action=>`<li><strong>${action.type==='fill'?'填写普通文本':'点击控件'} · ${esc(action.label||action.controlId)}</strong><small>控件编号 ${esc(action.controlId)}</small>${action.type==='fill'?`<pre>${esc(action.value)}</pre>`:''}</li>`).join('')}</ol></div><p class="modal-subtitle">审批绑定当前页面快照与动作摘要；页面变化时必须重新提案。结果未知不会自动重试。</p><div class="modal-error" role="alert"></div><div class="form-actions"><button class="secondary-button" data-action="cb-reject" data-id="${esc(a.id)}">拒绝这批动作</button><button class="primary-button" data-action="cb-approve" data-id="${esc(a.id)}" ${a.status!=='pending'?'disabled':''}>批准并执行这 ${a.actions.length} 个动作</button></div>`;}
async function controlledAction(name,id,el){const approval=array(state.browserApprovals).find(a=>a.id===id);const sessionId=approval?.sessionId||id;const session=array(state.controlledSessions).find(s=>s.id===sessionId);const key=name==='cb-open'?'open':name==='cb-cancel'?'cancel:'+sessionId:sessionId;if(controlledBusy.has(key))return;controlledBusy.add(key);if(el)el.disabled=true;try{if(name==='cb-open'){const result=await post('/api/controlled-browser/open',{targetId:id},{timeoutMs:60000});selectedControlledId=result.session?.id;await loadState(true);if(!controlledCancelled(result))toast('隔离页面已打开，尚未执行任何输入');}if(name==='cb-read'){const result=await api('/api/controlled-browser/'+encodeURIComponent(id)+'/read');controlledDrafts.delete(id);await loadState(true);if(!controlledCancelled(result))toast('已重新读取页面，旧的待提交动作已清空');}if(name==='cb-takeover'){const result=await post('/api/controlled-browser/'+encodeURIComponent(id)+'/takeover',{},{timeoutMs:60000});if(result.leaseToken&&!controlledCancelled(result))controlledLeases.set(id,result.leaseToken);controlledDrafts.delete(id);await loadState(true);if(result.leaseToken&&!controlledCancelled(result))toast('此窗口已取得人工控制权');}if(name==='cb-resume'){const leaseToken=controlledLeases.get(id);if(!leaseToken)throw new Error('此窗口没有当前人工控制权');const result=await post('/api/controlled-browser/'+encodeURIComponent(id)+'/resume',{leaseToken},{timeoutMs:60000});controlledLeases.delete(id);controlledDrafts.delete(id);await loadState(true);if(!controlledCancelled(result))toast('控制权已归还，旧输入审批失效');}if(name==='cb-cancel'){await post('/api/controlled-browser/'+encodeURIComponent(id)+'/cancel',{},{timeoutMs:60000});controlledLeases.delete(id);controlledDrafts.delete(id);await loadState(true);toast('会话已关闭；已发生的输入不会撤回');}if(name==='cb-propose'){const staged=controlledDrafts.get(id);if(!staged?.actions.length)throw new Error('请先加入明确动作');const result=await post('/api/controlled-browser/'+encodeURIComponent(id)+'/propose',{observationId:staged.observationId,actions:staged.actions,reason:'用户在受控工作台中准备的明确动作'});controlledDrafts.delete(id);await loadState(true);const a=result.approval||result;if(!array(state.browserApprovals).some(x=>x.id===a.id))state.browserApprovals=[a,...array(state.browserApprovals)];openModal('cb-approval',a.id);}if(name==='cb-approve'||name==='cb-reject'){if(!approval)throw new Error('审批记录尚未同步');const result=await post('/api/browser-approvals/'+encodeURIComponent(id),{decision:name==='cb-approve'?'approve':'reject',digest:approval.digest},{timeoutMs:360000});if(modal?.kind==='cb-approval'&&modal.id===id)closeModal();await loadState(true);const status=result.approval?.status;toast(status==='unknown'?'输入结果未知，请先读取核实；不会重试':status==='completed'?'已执行这批明确批准的动作':status==='rejected'?'已拒绝，未执行输入':'审批状态已更新，请检查记录',status==='unknown');}}catch(error){const node=$('#modal-root .modal-error');if(node)node.textContent=error.message;toast(error.message,true);}finally{controlledBusy.delete(key);if(el&&document.contains(el))el.disabled=false;if(view==='browser'&&!modal)render(true);}}

function openModal(kind,id){
 if(!modal){const active=document.activeElement;modalReturnFocus={node:active,action:active?.dataset?.action,nav:active?.dataset?.nav,id:active?.dataset?.id};}
 modal={kind,id,signature:kind==='notifications'?notificationSignature():''};let title='',body='',large=false;
 if(kind==='schedule'){const schedule=id?array(state.schedules).find(s=>s.id===id):null;if(id&&(!schedule||schedule.status==='cancelled')){closeModal();toast('此计划不可编辑',true);return;}title=schedule?'编辑周期任务':'新建周期任务';large=true;body=renderScheduleForm(schedule);}else if(kind==='schedule-cancel'){const schedule=array(state.schedules).find(s=>s.id===id);if(!schedule){closeModal();return;}title='取消周期任务';body=`<p class="modal-subtitle">确认取消「${esc(schedule.title)}」？取消后不再创建新任务，不能直接恢复；历史记录会保留。已经创建的任务会继续，请在任务中心单独处理。</p><div class="modal-error" role="alert"></div><div class="form-actions"><button class="secondary-button" data-action="close-modal">保留计划</button><button class="primary-button" data-action="schedule-cancel" data-id="${esc(id)}">确认取消计划</button></div>`;}else if(kind==='credential-forget'){title='删除已保存的凭据';body=`<p class="modal-subtitle">这会删除本机加密保存的凭据副本。之后启动需要重新输入；当前会话中已加载的凭据不会因此撤回。确定继续吗？</p><div class="modal-error" role="alert"></div><div class="form-actions"><button class="secondary-button" data-action="close-modal">保留凭据</button><button class="primary-button" data-action="confirm-forget-credentials">确认删除凭据</button></div>`;}else if(kind==='cb-target'){const target=id?array(state.browserTargets).find(t=>t.id===id):null;title=target?'配置允许的目标':'添加允许的目标';large=true;body=renderControlledTargetForm(target);}else if(kind==='cb-approval'){const a=array(state.browserApprovals).find(a=>a.id===id);if(!a){toast('审批记录不可用',true);closeModal();return;}title='确认网页输入动作';large=true;body=renderControlledApproval(a);}else if(kind==='mail-config'){title=id==='new'?'添加邮件账户':'邮件账户配置';large=true;body=renderMailConfigForm(id==='new'?null:mailAccount());}else if(kind==='mail-compose'){const draft=id?array(state.mailOutbox).find(d=>d.id===id):null;title=draft?'编辑真实邮件草稿':'新建真实邮件草稿';large=true;body=renderMailComposeForm(draft);}else if(kind==='mail-approval'){const approval=array(state.mailApprovals).find(a=>a.id===id);if(!approval){toast('审批记录尚未同步，请稍后重试',true);closeModal();return;}title='确认邮件发送';large=true;body=renderMailApproval(approval);}else if(kind==='mail-message'){const message=array(state.realInbox).find(m=>m.id===id);if(!message){closeModal();return;}title='真实收件箱 · 纯文本';large=true;body=`<h3 class="mail-message-subject">${esc(message.subject||'（无主题）')}</h3><div class="mail-addresses"><p><span>发件人</span>${esc(message.from)}</p><p><span>收件人</span>${esc(message.to)}</p><p><span>时间</span>${date(message.date||message.readAt)}</p></div>${message.truncated?'<div class="mail-error-note">正文因大小限制已截断，请到原邮箱查看完整内容。</div>':''}<div class="output-block mail-received-body">${esc(message.text||'（没有纯文本正文）')}</div>`;}else if(kind==='browser'){title='本地模拟 OA';large=true;const task=state.tasks.find(t=>String(t.browserSessionId)===String(id));const manual=task?.browserSession?.status==='manual';body=`<p class="modal-subtitle">${manual?'人工接管中。操作只保存到本地虚构演示库；关闭窗口不会归还控制权。':'当前仅查看。若需要手动提交，请先关闭此窗口并点击任务中的「手动接管」。'}</p><iframe class="oa-frame" title="本地模拟 OA 操作窗口" src="/fixture/oa?session=${encodeURIComponent(id)}"></iframe><div class="form-actions"><button class="secondary-button" data-action="close-modal">关闭窗口</button>${manual?`<button class="primary-button" data-action="browser-resume" data-id="${esc(id)}">归还控制权</button>`:''}</div>`;}else if(kind==='agent'){const a=id?getAgent(id):{};if(id&&!a){toast('这位智能体已不可用',true);return;}title=id?'配置智能体':'创建智能体';large=true;body=`<p class="modal-subtitle">给这位伙伴一个明确的角色，并按需授予工具权限。</p><form id="agent-form" data-id="${esc(id||'')}"><div class="form-row"><div class="form-field"><label for="agent-name">名称</label><input id="agent-name" name="name" value="${esc(a?.name||'')}" placeholder="例如：养护事务助手" required maxlength="40"></div><div class="form-field"><label for="agent-role">职责</label><input id="agent-role" name="role" value="${esc(a?.role||'')}" placeholder="例如：养护计划与周报整理" required maxlength="100"></div></div><div class="form-field"><label for="agent-personality">做事风格</label><textarea id="agent-personality" name="personality" placeholder="例如：严谨简洁，注明资料来源；信息不足时先指出缺口。" maxlength="1000">${esc(a?.personality||'')}</textarea></div>${renderAgentModelForm(a)}<div class="form-field"><label>工具权限</label><div class="permissions-grid">${Object.entries(permissions).map(([p,[label,desc]])=>`<label class="check-row"><input type="checkbox" name="permissions" value="${p}" ${(id?array(a?.permissions):['knowledge.read','workspace.write']).includes(p)?'checked':''}><span>${label}<small>${desc}</small></span></label>`).join('')}</div><div class="permission-warning">网页操作权限不会跳过审批；邮件草稿权限不包含发送邮件。</div></div><label class="check-row"><input type="checkbox" name="enabled" ${a?.enabled!==false?'checked':''}><span>启用此智能体</span></label><div class="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary-button" data-action="close-modal">取消</button><button type="submit" class="primary-button">${id?'保存更改':'创建智能体'}</button></div></form>`;
 }else if(kind==='memory'){title='添加一条知识';body=`<p class="modal-subtitle">内容保存在本地。请选择模型检索可见范围，再标明资料来源。</p><form id="memory-form">${renderMemoryScopeFields()}<div class="form-field"><label for="memory-title">标题</label><input id="memory-title" name="title" placeholder="例如：养护周报编写要求" required maxlength="150"></div><div class="form-field"><label for="memory-content">内容</label><textarea id="memory-content" name="content" placeholder="写下具体的背景、要求或资料内容…" style="min-height:160px" required maxlength="20000"></textarea></div><div class="form-field"><label for="memory-source">资料来源</label><input id="memory-source" name="source" placeholder="例如：内部工作手册 / 个人备注" value="手动添加" required maxlength="300"></div><div class="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary-button" data-action="close-modal">取消</button><button type="submit" class="primary-button">保存到知识库</button></div></form>`;
 }else if(kind==='reminder'){title='设一个工作提醒';const due=new Date(Date.now()+5*60*1000);const local=new Date(due.getTime()-due.getTimezoneOffset()*60000).toISOString().slice(0,16);body=`<p class="modal-subtitle">${heartbeatOn()?'本地服务保持运行时，到期会在工作台中提示。':'主动检查已关闭。提醒仍会保存，请开启左侧「主动检查」后接收到期提示。'}时间按这台设备的时区显示。</p><form id="reminder-form"><div class="form-field"><label for="reminder-title">提醒内容</label><input id="reminder-title" name="title" placeholder="例如：检查养护台账" value="检查台账" required maxlength="200"></div><div class="form-field"><label for="reminder-due">提醒时间</label><input id="reminder-due" name="dueAt" type="datetime-local" value="${local}" required></div><div class="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="secondary-button" data-action="close-modal">取消</button><button type="submit" class="primary-button">保存提醒</button></div></form>`;
 }else if(kind==='notifications'){title='提醒与待办';body=`<div class="section-heading"><h2>等待你确认</h2><span>${pendingApprovals().length+pendingMailApprovals().length} 项</span></div>${pendingApprovals().map(a=>`<div class="reminder-row">${icon('shield')}<div><strong>任务需要审批</strong><p>${esc(str(a.summary||'请查看任务详情'))}</p><button class="text-link" data-task="${esc(a.taskId)}" style="margin-top:8px;padding:0">查看并处理 ↗</button></div></div>`).join('')||(!pendingMailApprovals().length?'<p class="modal-subtitle">暂时没有等待审批的操作。</p>':'')}${pendingMailApprovals().map(a=>`<div class="reminder-row">${icon('mail')}<div><strong>真实邮件发送待审批</strong><p>${esc(a.snapshot?.subject||a.summary)}</p><button class="text-link" data-action="open-mail-approval" data-id="${esc(a.id)}" style="margin-top:8px;padding:0">审核完整邮件内容 ↗</button></div></div>`).join('')}<div class="section-heading" style="margin-top:28px"><h2>工作提醒</h2><button class="text-link" data-action="reminder">添加提醒 ＋</button></div>${state.reminders.map(r=>`<div class="reminder-row">${icon('clock')}<div><strong>${esc(r.title)}</strong><p>${date(r.dueAt,true)}</p></div>${badge(r.status||'scheduled')}</div>`).join('')||'<p class="modal-subtitle">还没有工作提醒。</p>'}${array(state.notifications).length?`<div class="section-heading" style="margin-top:26px"><h2>系统通知</h2></div>${state.notifications.slice(0,8).map(n=>`<div class="reminder-row">${icon('bell')}<div><strong>${esc(n.title||'系统通知')}</strong><p>${esc(str(n.message||n.body||n.content||''))}</p></div></div>`).join('')}`:''}`;
 }
 $('#modal-root').innerHTML=`<div class="modal-overlay" data-overlay><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭对话框">${icon('close')}</button></header><div class="modal-body">${body}</div></section></div>`;
 document.body.style.overflow='hidden';setTimeout(()=>$('#modal-root input, #modal-root button')?.focus(),30);
}
function closeModal(){const wasOpen=!!modal;modal=null;$('#modal-root').innerHTML='';document.body.style.overflow='';if(wasOpen){const saved=modalReturnFocus;let target=saved?.node;if(!target?.isConnected){target=[...document.querySelectorAll('[data-action],[data-nav]')].find(node=>(saved?.action?node.dataset.action===saved.action&&node.dataset.id===saved.id:saved?.nav&&node.dataset.nav===saved.nav));}(target||main).focus?.();modalReturnFocus=null;}}
async function loadState(force=false){
 if(pollBusy){if(!force)return;await new Promise(resolve=>refreshWaiters.push(resolve));return loadState(true);}pollBusy=true;
 try{const data=await api('/api/state');state={...state,...data,tasks:array(data.tasks),schedules:array(data.schedules),agents:array(data.agents),memories:array(data.memories),reminders:array(data.reminders),audit:array(data.audit),approvals:array(data.approvals)};online=true;const wasLoaded=loaded;loaded=true;const sig=JSON.stringify(state);if(force||sig!==lastSignature||!wasLoaded){lastSignature=sig;render(force);}else renderChrome();
 if(modal?.kind==='notifications'&&modal.signature!==notificationSignature()){const scroll=$('#modal-root .modal')?.scrollTop||0;openModal('notifications');const panel=$('#modal-root .modal');if(panel)panel.scrollTop=scroll;}
 for(const r of state.reminders){if(['fired','sent','due'].includes(r.status)&&!notificationSeen.has(r.id)){notificationSeen.add(r.id);if(wasLoaded)toast('提醒：'+r.title);}}
 }catch(err){online=false;renderChrome();if(!loaded)render();if(force)toast(err.message||'无法连接本地服务',true);}finally{pollBusy=false;refreshWaiters.splice(0).forEach(resolve=>resolve());}
}
async function createTask(form){if(submitting)return;const fd=new FormData(form);const prompt=String(fd.get('prompt')||'').trim();if(!prompt)return;const submittedVersion=draftVersion,submittedNavigation=navigationVersion,payload={prompt,agentId:fd.get('agentId')||undefined,budget:Number(state.settings.budget)||20},payloadSignature=JSON.stringify(payload);if(!pendingSubmission||pendingSubmission.version!==submittedVersion||pendingSubmission.signature!==payloadSignature)pendingSubmission={id:crypto.randomUUID(),version:submittedVersion,signature:payloadSignature};const submission=pendingSubmission;submitting=true;const button=form.querySelector('button[type="submit"]');button.disabled=true;button.innerHTML='<span class="spinner"></span><span>提交中</span>';
 try{const result=await post('/api/tasks',{...payload,submissionId:submission.id});const task=result.task||result;if(pendingSubmission===submission)pendingSubmission=null;if(draftVersion===submittedVersion)draft='';if(navigationVersion===submittedNavigation)selectedTaskId=task.id;await loadState();if(view==='chat'&&navigationVersion===submittedNavigation){selectActiveChat(task.id);render(true);$('.chat-thread')?.scrollIntoView({block:'start',behavior:'smooth'});}toast('任务已创建，执行过程会实时更新');}catch(err){toast(err.message,true);}finally{submitting=false;const currentButton=$('#task-form button[type="submit"]');if(currentButton){currentButton.disabled=false;currentButton.classList.remove('loading-button');currentButton.innerHTML='<span>发送</span>'+icon('send');}}
}
async function handleForm(form){
 const formId=form.getAttribute('id'),submittedNavigation=navigationVersion;
 const finishModalForm=async()=>{const current=document.contains(form)&&navigationVersion===submittedNavigation;if(current)closeModal();await loadState(current&&view!=='settings');return current;};
 if(formId==='task-form'){await createTask(form);return;}
 const fd=new FormData(form);const submit=form.querySelector('[type="submit"]');if(submit?.disabled)return;if(submit)submit.disabled=true;const errorNode=form.querySelector('.modal-error');if(errorNode)errorNode.textContent='';
 try{
 if(formId==='agent-form'){const body={name:fd.get('name').trim(),role:fd.get('role').trim(),personality:fd.get('personality').trim(),permissions:fd.getAll('permissions'),enabled:fd.has('enabled'),modelConfig:fd.has('inheritModel')?{inherit:true}:{inherit:false,endpoint:String(fd.get('roleEndpoint')||'').trim(),model:String(fd.get('roleModel')||'').trim()}};if(!body.modelConfig.inherit){if(!body.modelConfig.endpoint.startsWith('https://'))throw new Error('独立模型端点必须使用 HTTPS');const key=String(fd.get('roleApiKey')||'').trim();if(key)body.apiKey=key;if(fd.has('clearRoleApiKey'))body.clearApiKey=true;}await api(form.dataset.id?'/api/agents/'+encodeURIComponent(form.dataset.id):'/api/agents',{method:form.dataset.id?'PUT':'POST',body:JSON.stringify(body)});await finishModalForm();toast('智能体配置已保存');}
 if(formId==='schedule-form'){const type=String(fd.get('recurrenceType')),timezone=String(fd.get('timezone')||'').trim();try{new Intl.DateTimeFormat('zh-CN',{timeZone:timezone}).format();}catch{throw new Error('请输入有效的 IANA 时区，例如 Asia/Shanghai');}const recurrence={type};if(type==='interval'){recurrence.intervalMinutes=Number(fd.get('intervalMinutes'));if(!Number.isInteger(recurrence.intervalMinutes)||recurrence.intervalMinutes<1)throw new Error('间隔必须是至少 1 分钟的整数');}else{recurrence.time=String(fd.get('time')||'');if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(recurrence.time))throw new Error('请选择有效的当地时间');if(type==='weekly'){recurrence.daysOfWeek=fd.getAll('daysOfWeek').map(Number);if(!recurrence.daysOfWeek.length)throw new Error('每周计划请至少选择一天');}}const body={title:String(fd.get('title')||'').trim(),prompt:String(fd.get('prompt')||'').trim(),agentId:String(fd.get('agentId')||'')||'coordinator',budget:Number(fd.get('budget')),timezone,recurrence};if(!body.title||!body.prompt)throw new Error('请填写计划名称和任务内容');await api(form.dataset.id?'/api/schedules/'+encodeURIComponent(form.dataset.id):'/api/schedules',{method:form.dataset.id?'PATCH':'POST',body:JSON.stringify(body)});await finishModalForm();toast('周期任务已保存，请核对下次执行时间');}
 if(formId==='desktop-preferences-form'){if(!state.desktop?.available||!state.desktop.trayAvailable)throw new Error('当前没有可用的桌面托盘');await post('/api/desktop/preferences',{backgroundEnabled:fd.has('backgroundEnabled')});await refreshDesktopSettings();toast('桌面运行偏好已保存');}
 if(formId==='desktop-credentials-form'){if(!state.desktop?.credentialVault?.available)throw new Error('系统安全存储不可用，未保存凭据');if(!fd.has('credentialConsent'))throw new Error('请先明确同意加密保存当前凭据');await post('/api/desktop/credentials/save',{confirmed:true});await refreshDesktopSettings();toast('当前凭据已加密保存到本机');}
 if(formId==='memory-form'){await post('/api/memories',{title:fd.get('title').trim(),content:fd.get('content').trim(),source:fd.get('source').trim(),scope:fd.get('scope')||'workspace',ownerAgentId:fd.get('scope')==='agent'?fd.get('ownerAgentId'):null});await finishModalForm();toast('知识已保存到本地');}
 if(formId==='reminder-form'){const due=new Date(fd.get('dueAt'));if(Number.isNaN(due.getTime())||due.getTime()<=Date.now())throw new Error('请选择一个未来的提醒时间');await post('/api/reminders',{title:fd.get('title').trim(),dueAt:due.toISOString()});await finishModalForm();toast('提醒已保存：'+date(due));}
 if(formId==='mail-config-form'){const body={accountId:String(fd.get('accountId')).trim(),from:String(fd.get('from')).trim()};for(const p of ['imap','smtp']){body[p]={host:String(fd.get(p+'Host')).trim(),port:Number(fd.get(p+'Port')),secure:fd.get(p+'Secure')==='true',user:String(fd.get(p+'User')).trim()};const secret=String(fd.get(p+'Password')||'');if(secret)body[p].password=secret;}await post('/api/mail/config',body,{timeoutMs:45000});mailAccountId=body.accountId;await finishModalForm();toast('邮箱配置已保存；尚未读取或发送邮件');}
 if(formId==='mail-draft-form'){const body={accountId:fd.get('accountId'),to:String(fd.get('to')).split(/[，,;；]/).map(x=>x.trim()).filter(Boolean),subject:String(fd.get('subject')).trim(),text:String(fd.get('text'))};const result=form.dataset.id?await api('/api/mail/drafts/'+encodeURIComponent(form.dataset.id),{method:'PUT',body:JSON.stringify(body)}):await post('/api/mail/drafts',body);selectedMailId=result.id||result.draft?.id;mailTab='outbox';if(await finishModalForm())render(true);toast('已保存本地草稿，尚未发送');}
 if(formId==='controlled-target-form'){const target={id:String(fd.get('targetId')).trim(),name:String(fd.get('name')).trim(),startUrl:String(fd.get('startUrl')).trim(),enabled:fd.has('enabled')};const origins=String(fd.get('allowedOrigins')||'').split(/\n/).map(s=>s.trim()).filter(Boolean);if(origins.length)target.allowedOrigins=origins;const others=array(state.browserTargets).filter(t=>t.id!==target.id).map(({id,name,startUrl,allowedOrigins,enabled})=>({id,name,startUrl,allowedOrigins,enabled}));await post('/api/browser-targets',{targets:[...others,target]},{timeoutMs:60000});await finishModalForm();toast('目标边界已保存，尚未打开网站');}
 if(formId==='controlled-action-form'){const id=form.dataset.id,session=array(state.controlledSessions).find(s=>s.id===id),obs=session?.lastObservation;if(!obs||form.dataset.observationId!==obs.observationId)throw new Error('页面观察已更新，请重新读取再准备动作');const control=obs.controls.find(c=>c.controlId===fd.get('controlId'));if(!control||control.sensitive||control.forbidden||!control.enabled)throw new Error('此控件不可操作');const action={type:fd.get('type'),controlId:control.controlId};if(action.type==='fill'){if(!control.fillable)throw new Error('此控件不是普通文本输入');action.value=String(fd.get('value')||'');}if(session.status==='manual'){const leaseToken=controlledLeases.get(id);if(!leaseToken)throw new Error('此窗口没有当前人工控制权');controlledBusy.add(id);try{await post('/api/controlled-browser/'+encodeURIComponent(id)+'/manual',{leaseToken,observationId:obs.observationId,action},{timeoutMs:60000});await loadState(true);toast('人工动作已执行；请核实页面结果');}finally{controlledBusy.delete(id);if(view==='browser'&&!modal)render(true);}}else{const staged=controlledDrafts.get(id);const actions=staged?.observationId===obs.observationId?[...staged.actions]:[];if(actions.length>=8)throw new Error('每批最多 8 个动作');actions.push(action);controlledDrafts.set(id,{observationId:obs.observationId,actions});render(true);toast('已加入待审批动作，尚未输入页面');}}
 if(formId==='settings-form'){const body={mode:fd.get('mode'),endpoint:fd.get('endpoint').trim(),model:fd.get('model').trim(),budget:Number(fd.get('budget'))};if(body.endpoint&&!body.endpoint.startsWith('https://'))throw new Error('模型端点必须使用 HTTPS');if(body.mode==='api'&&(!body.endpoint||!body.model))throw new Error('请填写模型端点与模型名称');if(fd.get('apiKey').trim())body.apiKey=fd.get('apiKey').trim();await post('/api/settings',body);const key=form.querySelector('[name="apiKey"]');if(key)key.value='';await loadState(true);toast('配置已保存');}
 }catch(err){if(errorNode)errorNode.textContent=err.message;else{toast(err.message,true);const status=$('#settings-status');if(status)status.textContent=err.message;}}finally{if(submit&&document.contains(submit))submit.disabled=formId==='desktop-credentials-form'&&(!form.querySelector('[name="credentialConsent"]')?.checked||!state.desktop?.credentialVault?.available);}
}
function uiActionKey(name,id){return (['approve','reject'].includes(name)?'approval':name.startsWith('browser-')?'browser':name)+':'+(id||'global');}
function applyBusyButtons(){document.querySelectorAll('[data-action]').forEach(el=>{const busy=actionBusy.has(uiActionKey(el.dataset.action,el.dataset.id));if(busy){el.dataset.uiBusy='true';el.disabled=true;el.setAttribute('aria-busy','true');}else if(el.dataset.uiBusy){delete el.dataset.uiBusy;el.disabled=false;el.removeAttribute('aria-busy');}});}
async function action(name,el){
 const id=el?.dataset.id;
 if(name==='toggle-overview'){overviewOpen=!overviewOpen;render(true);$('.overview-toggle')?.focus();return;}
 if(name==='toggle-options'){optionsOpen=!optionsOpen;const panel=$('#composer-options');if(panel)panel.hidden=!optionsOpen;el?.setAttribute('aria-expanded',String(optionsOpen));if(optionsOpen)$('#agent-select')?.focus();return;}
 if(name==='toggle-tools'){toolsOpen=!toolsOpen;renderChrome();$('[data-action="toggle-tools"]')?.focus();return;}
 if(name==='new-task'){closeModal();pendingSubmission=null;selectActiveChat(null);navigate('chat');setTimeout(()=>$('#prompt-input')?.focus(),30);return;}
 if(name==='sample'){draft=draft.trim()?draft+'\n'+el.dataset.prompt:el.dataset.prompt;draftVersion++;navigate('chat');$('#prompt-input')?.focus();return;}
 if(name==='toggle-nav'){document.body.classList.toggle('nav-open');return;}
 if(name==='close-nav'){document.body.classList.remove('nav-open');return;}
 if(name==='close-modal'){closeModal();return;}
 if(name==='add-schedule'){openModal('schedule');return;}
 if(name==='edit-schedule'){openModal('schedule',id);return;}
 if(name==='cancel-schedule'){openModal('schedule-cancel',id);return;}
 if(name.startsWith('schedule-')){await scheduleAction(name,id,el);return;}
 if(name==='export-task'){await exportTask(id,el.dataset.format);return;}
 if(name==='forget-credentials'){openModal('credential-forget');return;}
 if(name==='add-agent'){openModal('agent');return;}
 if(name==='edit-agent'){openModal('agent',id);return;}
 if(name==='add-memory'){openModal('memory');return;}
 if(name==='reminder'){openModal('reminder');return;}
 if(name==='notifications'){openModal('notifications');return;}
 if(name==='open-mail-approval'){mailTab='outbox';const a=array(state.mailApprovals).find(a=>a.id===id);if(a)selectedMailId=a.draftId;navigate('mail');openModal('mail-approval',id);return;}
 if(name==='open-mail-draft'){selectedMailId=id;mailTab='outbox';const draft=array(state.mailOutbox).find(d=>d.id===id);if(draft)mailAccountId=draft.accountId;navigate('mail');return;}
 if(name==='mail-config'){openModal('mail-config');return;}
 if(name==='mail-new-account'){openModal('mail-config','new');return;}
 if(name==='open-controlled-session'){selectedControlledId=id;navigate('browser');return;}
 if(name==='open-controlled-approval'){const approval=array(state.browserApprovals).find(a=>a.id===id);if(approval)selectedControlledId=approval.sessionId;navigate('browser');openModal('cb-approval',id);return;}
 if(name==='cb-add-target'){openModal('cb-target');return;}
 if(name==='cb-edit-target'){openModal('cb-target',id);return;}
 if(name==='cb-review'){openModal('cb-approval',id);return;}
 if(name==='cb-clear-actions'){controlledDrafts.delete(id);render(true);return;}
 if(name==='cb-remove-action'){const staged=controlledDrafts.get(id);if(staged)staged.actions.splice(Number(el.dataset.index),1);render(true);return;}
 if(name.startsWith('cb-')){await controlledAction(name,id,el);return;}
 if(name==='mail-edit'){openModal('mail-compose',id);return;}
 if(name==='mail-compose'){if(!mailAccount()?.smtp){toast('请先配置 SMTP 邮件账户',true);return;}openModal('mail-compose');return;}
 if(name==='mail-message'){openModal('mail-message',id);return;}
 if(name==='mail-review'){openModal('mail-approval',id);return;}
 if(name.startsWith('mail-')){await mailAction(name,id,el);return;}
 if(name==='view-browser'){openModal('browser',id);return;}
 if(name==='refresh'){await loadState(true);return;}
 if(name==='retry-task'){const t=state.tasks.find(t=>String(t.id)===String(id));if(t){draft=t.prompt;draftAgent=t.agentId;draftVersion++;pendingSubmission=null;navigate('chat');$('#prompt-input')?.focus();}return;}
 if(name==='copy-connection-diagnostic'){if(!connectionDiagnostic)return;try{await navigator.clipboard.writeText(connectionDiagnostic);toast('已复制诊断编号和固定说明，不含密钥或请求内容');}catch{toast('无法访问剪贴板，请复制下方诊断编号',true);}return;}
 if(name==='copy-output'){const t=state.tasks.find(t=>String(t.id)===String(id));try{await navigator.clipboard.writeText(str(t?.output));toast('结果已复制');}catch{toast('无法访问剪贴板，请直接选中结果复制',true);}return;}
 const busyKey=uiActionKey(name,id);if(el?.disabled||actionBusy.has(busyKey))return;actionBusy.add(busyKey);applyBusyButtons();if(el)el.disabled=true;
 try{
 if(name==='confirm-forget-credentials'){await post('/api/desktop/credentials/forget',{confirmed:true});if(modal?.kind==='credential-forget')closeModal();await refreshDesktopSettings();toast('已删除加密保存的凭据；当前会话仍可继续使用');}
 if(name==='heartbeat'){await post('/api/heartbeat',{enabled:!heartbeatOn()});await loadState(true);toast(heartbeatOn()?'主动检查已开启':'主动检查已关闭');}
 if(name==='cancel-task'){await post('/api/tasks/'+encodeURIComponent(id)+'/cancel');await loadState(true);toast('任务已取消');}
 if(name==='approve'||name==='reject'){await post('/api/approvals/'+encodeURIComponent(id),{decision:name==='approve'?'approve':'reject'},{timeoutMs:300000});await loadState(true);toast(name==='approve'?'已批准，任务继续执行':'已拒绝本次操作');}
 if(name==='test-api'){const status=$('#settings-status');if(status)status.textContent='正在测试已保存的连接…';connectionDiagnostic=null;const copyButton=$('[data-action="copy-connection-diagnostic"]');if(copyButton)copyButton.hidden=true;const result=await post('/api/settings/test',{},{timeoutMs:45000});const text=result.message||result.result||result.status||(result.ok===false?'连接测试失败':'连接测试成功');if(status)status.textContent=str(text);toast(str(text),result.ok===false);}
 if(name==='browser-takeover'||name==='browser-resume'){const takeover=name==='browser-takeover';await post('/api/browser/'+encodeURIComponent(id)+(takeover?'/takeover':'/resume'));await loadState(true);if(takeover)openModal('browser',id);else if(modal?.kind==='browser')closeModal();toast(takeover?'已进入手动接管，自动操作已暂停':'已归还控制权，请确认原计划后继续');}
 }catch(err){toast(err.message,true);if(name==='test-api'&&$('#settings-status')){const code=err.code&&/^(MODEL_|ENDPOINT_|KEY_MISSING|CANCELLED)/.test(err.code)?err.code:'MODEL_CONNECTION_FAILED';$('#settings-status').textContent=err.message+'\n诊断编号：'+code;connectionDiagnostic='路衡 v0.4 连接诊断\n诊断编号：'+code+'\n时间：'+new Date().toISOString()+'\n不含密钥、服务地址、账号或请求内容。';const copyButton=$('[data-action="copy-connection-diagnostic"]');if(copyButton)copyButton.hidden=false;}}finally{actionBusy.delete(busyKey);applyBusyButtons();if(el&&document.contains(el))el.disabled=false;}
}

async function mailAction(name,id,el){const account=mailAccount();const approval=array(state.mailApprovals).find(a=>a.id===id);const key=name==='mail-fetch'?'fetch':name==='mail-cancel'?'cancel:'+id:approval?.draftId||id;if(mailBusy.has(key))return;mailBusy.add(key);if(el)el.disabled=true;try{if(name==='mail-fetch'){if(!account?.hasCredentials?.imap)throw new Error('请先配置 IMAP 凭据');const result=await post('/api/mail/inbox',{accountId:account.accountId,limit:50},{timeoutMs:90000});await loadState(true);toast(`已读取 ${array(result.messages).length} 封新邮件${result.hasMore?'；仍有更多可继续读取':''}`);}if(name==='mail-request-send'){const result=await post('/api/mail/drafts/'+encodeURIComponent(id)+'/request-send');await loadState(true);const record=result.approval||result;if(record.id&&!array(state.mailApprovals).some(a=>a.id===record.id))state.mailApprovals=[record,...array(state.mailApprovals)];mailBusy.delete(key);openModal('mail-approval',record.id);}if(name==='mail-approve'||name==='mail-reject'){const result=await post('/api/mail/approvals/'+encodeURIComponent(id),{decision:name==='mail-approve'?'approve':'reject'},{timeoutMs:300000});if(modal?.kind==='mail-approval'&&modal.id===id)closeModal();await loadState(true);const sent=result.draft||result;toast(sent.status==='unknown'?'发送结果不确定，请勿重试；请核对服务商记录':name==='mail-reject'?'已拒绝本次发送':sent.status==='sent'?'邮件服务器已接受这封邮件':'发送状态已更新，请查看详情',sent.status==='unknown'||sent.status==='failed');}if(name==='mail-cancel'){await post('/api/mail/drafts/'+encodeURIComponent(id)+'/cancel');await loadState(true);toast('停止请求已处理，请核对当前发送状态');}}catch(err){const error=$('#modal-root .modal-error');if(error)error.textContent=err.message;toast(err.message,true);}finally{mailBusy.delete(key);if(el&&document.contains(el))el.disabled=false;if(view==='mail'&&!modal)render(true);}}

document.addEventListener('click',e=>{
 const summary=e.target.closest('summary');if(summary?.parentElement.dataset.executionTask)executionOpen.set(summary.parentElement.dataset.executionTask,!summary.parentElement.open);
 const nav=e.target.closest('[data-nav]');if(nav){closeModal();navigate(nav.dataset.nav);return;}
 const task=e.target.closest('[data-task]');if(task){selectedTaskId=task.dataset.task;closeModal();if(view!=='tasks')navigate('tasks');else render(true);return;}
 const controlled=e.target.closest('[data-controlled-session]');if(controlled){selectedControlledId=controlled.dataset.controlledSession;render(true);return;}
 const mailTabButton=e.target.closest('[data-mail-tab]');if(mailTabButton){mailTab=mailTabButton.dataset.mailTab;render(true);return;}
 const mailDraft=e.target.closest('[data-mail-draft]');if(mailDraft){selectedMailId=mailDraft.dataset.mailDraft;render(true);return;}
 const filter=e.target.closest('[data-filter]');if(filter){taskFilter=filter.dataset.filter;render(true);return;}
 const control=e.target.closest('[data-action]');if(control){action(control.dataset.action,control);return;}
 if(e.target.matches('[data-overlay]'))closeModal();
});
document.addEventListener('submit',e=>{if(['task-form','agent-form','memory-form','reminder-form','schedule-form','desktop-preferences-form','desktop-credentials-form','settings-form','mail-config-form','mail-draft-form','controlled-target-form','controlled-action-form'].includes(e.target.getAttribute('id'))){e.preventDefault();handleForm(e.target);}});
document.addEventListener('input',e=>{if(e.target.id==='prompt-input'){draft=e.target.value;draftVersion++;}if(e.target.id==='task-search'){search=e.target.value;const pos=e.target.selectionStart;render(true);const field=$('#task-search');field?.focus();field?.setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.id==='schedule-recurrence')syncScheduleFields();if(e.target.id==='desktop-credential-consent')$('#desktop-save-credentials').disabled=!e.target.checked||!state.desktop?.credentialVault?.available;if(e.target.id==='agent-select'){draftAgent=e.target.value;draftVersion++;}if(e.target.id==='agent-inherit-model'){const inherit=e.target.checked;const section=$('#agent-own-model');section.hidden=inherit;section.querySelectorAll('input').forEach(input=>{input.disabled=inherit;if(['agent-endpoint','agent-model'].includes(input.id))input.required=!inherit;});}if(e.target.id==='cb-control'){const option=e.target.selectedOptions[0];const fill=$('#cb-action-type option[value="fill"]');fill.disabled=option.dataset.fillable!=='true';if(fill.disabled&&$('#cb-action-type').value==='fill'){$('#cb-action-type').value='click';$('#cb-value-field').hidden=true;$('#cb-value').disabled=true;}}if(e.target.id==='cb-action-type'){const filling=e.target.value==='fill';$('#cb-value-field').hidden=!filling;$('#cb-value').disabled=!filling;}if(e.target.id==='mail-account-select'){mailAccountId=e.target.value;selectedMailId=null;render(true);}if(e.target.dataset.mailProtocol){const protocol=e.target.dataset.mailProtocol;$('#'+protocol+'-port').value=protocol==='imap'?(e.target.value==='true'?993:143):(e.target.value==='true'?465:587);}if(e.target.id==='memory-scope'){const privateScope=e.target.value==='agent';$('#memory-owner-field').hidden=!privateScope;$('#memory-owner').disabled=!privateScope;$('#memory-owner').required=privateScope;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.body.classList.remove('nav-open');}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();action('new-task');}if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&e.target.id==='prompt-input'){e.preventDefault();$('#task-form')?.requestSubmit();}if(e.key==='Tab'&&modal){const focusable=[...$('#modal-root').querySelectorAll('button,input,textarea,select,a[href]')].filter(el=>!el.disabled&&!el.closest('[hidden]'));if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('error',e=>{if(e.target.matches?.('[data-browser-image]')){const replacement=document.createElement('div');replacement.className='browser-unavailable';replacement.textContent='当前截图暂不可用，可打开模拟 OA 查看执行现场。';e.target.replaceWith(replacement);}},true);
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'chat';if(views[next]&&view!==next){closeModal();document.body.classList.remove('nav-open');view=next;navigationVersion++;search='';render(true);}});
document.addEventListener('toggle',e=>{if(!e.target.isConnected)return;if(e.target.matches?.('.recent-section'))recentOpen=e.target.open;},true);
document.addEventListener('focusout',()=>{setTimeout(()=>{if(pendingRender&&!modal&&view!=='settings')render();},0);});
window.addEventListener('online',()=>loadState(true));
renderChrome();loadState();setInterval(()=>loadState(),2000);
